package com.potionprep;

import java.util.EnumSet;
import java.util.HashMap;
import java.util.Map;
import java.util.Set;
import net.runelite.api.Client;
import net.runelite.api.EnumComposition;
import net.runelite.api.EnumID;
import net.runelite.api.Quest;
import net.runelite.api.QuestState;
import net.runelite.api.Skill;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.VarbitID;

/** Reads the parts of {@link FarmPlan.Account} that come from the game. Client thread only. */
final class AccountReader
{
	/** Quests the herb run cares about (patch access and teleport spells). */
	static final Quest[] QUESTS = {
		Quest.PRIEST_IN_PERIL, Quest.MY_ARMS_BIG_ADVENTURE, Quest.MAKING_FRIENDS_WITH_MY_ARM,
		Quest.CHILDREN_OF_THE_SUN, Quest.PLAGUE_CITY, Quest.EADGARS_RUSE, Quest.LUNAR_DIPLOMACY,
		Quest.THE_GREAT_BRAIN_ROBBERY, Quest.TWILIGHTS_PROMISE,
	};

	static final int[] POUCH_TYPES = {VarbitID.RUNE_POUCH_TYPE_1, VarbitID.RUNE_POUCH_TYPE_2, VarbitID.RUNE_POUCH_TYPE_3,
		VarbitID.RUNE_POUCH_TYPE_4, VarbitID.RUNE_POUCH_TYPE_5, VarbitID.RUNE_POUCH_TYPE_6};
	static final int[] POUCH_AMOUNTS = {VarbitID.RUNE_POUCH_QUANTITY_1, VarbitID.RUNE_POUCH_QUANTITY_2,
		VarbitID.RUNE_POUCH_QUANTITY_3, VarbitID.RUNE_POUCH_QUANTITY_4, VarbitID.RUNE_POUCH_QUANTITY_5,
		VarbitID.RUNE_POUCH_QUANTITY_6};

	/** Varbits that change the account snapshot (besides the leprechaun ones). */
	static final int[] VARBITS;

	static
	{
		int[] v = new int[POUCH_TYPES.length * 2 + 2];
		// Spellbook, diaries and house location change what's usable.
		System.arraycopy(POUCH_TYPES, 0, v, 0, POUCH_TYPES.length);
		System.arraycopy(POUCH_AMOUNTS, 0, v, POUCH_TYPES.length, POUCH_AMOUNTS.length);
		v[v.length - 2] = VarbitID.SPELLBOOK;
		v[v.length - 1] = VarbitID.MORYTANIA_DIARY_ELITE_COMPLETE;
		v = java.util.Arrays.copyOf(v, v.length + 3);
		v[v.length - 3] = VarbitID.LUMBRIDGE_DIARY_ELITE_COMPLETE;
		v[v.length - 2] = VarbitID.POH_HOUSE_LOCATION;
		v[v.length - 1] = VarbitID.FARMING_BLOCKWEEDS;
		VARBITS = v;
	}

	private AccountReader()
	{
	}

	/** Runs a client script per quest, so call it outside other scripts (e.g. ClientTick). */
	static Set<Quest> quests(Client client)
	{
		Set<Quest> done = EnumSet.noneOf(Quest.class);
		for (Quest q : QUESTS)
		{
			if (q.getState(client) == QuestState.FINISHED)
			{
				done.add(q);
			}
		}
		return done;
	}

	/** Fairy rings work once you've reached the Fairy Godfather in Fairytale II (quest varbit 40+). */
	static boolean fairyRings(Client client)
	{
		return client.getVarbitValue(VarbitID.FAIRY2_QUEENCURE_QUEST) >= 40;
	}

	static FarmPlan.Account read(Client client, Set<Quest> quests, Boolean fairyRings, Set<String> portals,
		Set<Integer> worn, boolean ownsPouch)
	{
		return FarmPlan.Account.builder()
			.fairyRings(fairyRings)
			.kandarinDiary(client.getVarbitValue(VarbitID.KANDARIN_DIARY_ELITE_COMPLETE) == 1 ? 3
				: client.getVarbitValue(VarbitID.KANDARIN_DIARY_HARD_COMPLETE) == 1 ? 2
				: client.getVarbitValue(VarbitID.KANDARIN_DIARY_MEDIUM_COMPLETE) == 1 ? 1 : 0)
			// FARMING_BLOCKWEEDS: 0 not bought, 1 off, 2 on.
			.autoweed(client.getVarbitValue(VarbitID.FARMING_BLOCKWEEDS) == 2)
			.kourendEasy(client.getVarbitValue(VarbitID.KOUREND_DIARY_EASY_COMPLETE) == 1)
			.kourendHard(client.getVarbitValue(VarbitID.KOUREND_DIARY_HARD_COMPLETE) == 1)
			.lumbridgeElite(client.getVarbitValue(VarbitID.LUMBRIDGE_DIARY_ELITE_COMPLETE) == 1)
			.houseLocation(client.getVarbitValue(VarbitID.POH_HOUSE_LOCATION))
			.portals(portals)
			.farming(client.getRealSkillLevel(Skill.FARMING))
			.magic(client.getBoostedSkillLevel(Skill.MAGIC))
			.spellbook(client.getVarbitValue(VarbitID.SPELLBOOK))
			.quests(quests)
			.moryElite(client.getVarbitValue(VarbitID.MORYTANIA_DIARY_ELITE_COMPLETE) == 1)
			.leprechaun(ToolLeprechaun.read(client::getVarbitValue))
			.pouch(ownsPouch ? pouch(client) : new HashMap<>())
			.staffElements(staffElements(worn))
			.build();
	}

	private static Map<Integer, Integer> pouch(Client client)
	{
		Map<Integer, Integer> out = new HashMap<>();
		EnumComposition runes = client.getEnum(EnumID.RUNEPOUCH_RUNE);
		if (runes == null)
		{
			return out;
		}
		for (int i = 0; i < POUCH_TYPES.length; i++)
		{
			int type = client.getVarbitValue(POUCH_TYPES[i]);
			int amount = client.getVarbitValue(POUCH_AMOUNTS[i]);
			int id = type > 0 ? runes.getIntValue(type) : -1;
			if (id > 0 && amount > 0)
			{
				out.merge(id, amount, Integer::sum);
			}
		}
		return out;
	}

	/** Air 1, water 2, earth 4, fire 8, as in {@link Farm.Rune}. */
	static int staffElements(Set<Integer> worn)
	{
		int bits = 0;
		for (int id : worn)
		{
			bits |= staff(id);
		}
		return bits;
	}

	private static int staff(int id)
	{
		switch (id)
		{
			case ItemID.STAFF_OF_AIR:
			case ItemID.AIR_BATTLESTAFF:
			case ItemID.MYSTIC_AIR_STAFF:
				return 1;
			case ItemID.STAFF_OF_WATER:
			case ItemID.WATER_BATTLESTAFF:
			case ItemID.MYSTIC_WATER_STAFF:
				return 2;
			case ItemID.STAFF_OF_EARTH:
			case ItemID.EARTH_BATTLESTAFF:
			case ItemID.MYSTIC_EARTH_STAFF:
				return 4;
			case ItemID.STAFF_OF_FIRE:
			case ItemID.FIRE_BATTLESTAFF:
			case ItemID.MYSTIC_FIRE_STAFF:
				return 8;
			case ItemID.MIST_BATTLESTAFF:
			case ItemID.MYSTIC_MIST_BATTLESTAFF:
				return 1 | 2;
			case ItemID.DUST_BATTLESTAFF:
			case ItemID.MYSTIC_DUST_BATTLESTAFF:
				return 1 | 4;
			case ItemID.MUD_BATTLESTAFF:
			case ItemID.MYSTIC_MUD_STAFF:
				return 2 | 4;
			case ItemID.SMOKE_BATTLESTAFF:
			case ItemID.MYSTIC_SMOKE_BATTLESTAFF:
				return 1 | 8;
			case ItemID.STEAM_BATTLESTAFF:
			case ItemID.MYSTIC_STEAM_BATTLESTAFF:
			case ItemID.STEAM_BATTLESTAFF_PRETTY:
			case ItemID.MYSTIC_STEAM_BATTLESTAFF_PRETTY:
				return 2 | 8;
			case ItemID.LAVA_BATTLESTAFF:
			case ItemID.MYSTIC_LAVA_STAFF:
			case ItemID.LAVA_BATTLESTAFF_PRETTY:
			case ItemID.MYSTIC_LAVA_STAFF_PRETTY:
				return 4 | 8;
			// Tomes (off-hand) count as unlimited runes of their element.
			case ItemID.TOME_OF_FIRE:
				return 8;
			case ItemID.TOME_OF_WATER:
				return 2;
			case ItemID.TOME_OF_EARTH:
				return 4;
			case ItemID.TWINFLAME_STAFF:
				return 2 | 8;
			case ItemID.SHADOWFLAME_QUADRANT:
				return 1 | 2 | 4 | 8;
			default:
				return 0;
		}
	}
}

package com.potionprep;

import java.util.regex.Matcher;
import java.util.regex.Pattern;
import lombok.Getter;

/**
 * Uses left in the bottomless compost bucket and what it holds. The game
 * only shows these in chat (Check, filling, using it) and, for a bucket
 * stored with a tool leprechaun, in the leprechaun's varbits. The plugin
 * saves the result per account so it survives logging out.
 *
 * Type: 0 unknown, 1 compost, 2 supercompost, 3 ultracompost.
 */
@Getter
final class BottomlessBucket
{
	private static final String TYPES = "(ultracompost|supercompost|compost)";
	private static final String COUNT = "([\\d,]+|one|a single)";
	static final Pattern CHECK = Pattern.compile(
		"Your bottomless compost bucket is currently holding " + COUNT + " uses? of " + TYPES);
	static final Pattern EMPTY = Pattern.compile(
		"Your (?:bottomless )?compost bucket (?:is currently empty|has run out)");
	static final Pattern FILL_TYPE = Pattern.compile(
		"You fill your bottomless compost bucket with (?:a single bucket|[\\d,]+ buckets) of " + TYPES);
	static final Pattern FILL_TOTAL = Pattern.compile(
		"Your bottomless compost bucket now contains a total of " + COUNT + " uses?");
	/** Sent after a use on some accounts: "Your bottomless compost bucket has 12 uses of ultracompost remaining." */
	static final Pattern LEFT = Pattern.compile(
		"Your bottomless compost bucket has " + COUNT + " uses? (?:of " + TYPES + " )?(?:left|remaining)");
	/** As in RuneLite's CompostTracker. */
	static final Pattern TREATED = Pattern.compile("You treat the .+ with (ultra|super|)compost");

	/** Uses left, -1 if not known. */
	private int uses;
	private int type;
	/** A use seen this tick, applied at the end of it unless the game also said how many are left. */
	private boolean pendingUse;

	BottomlessBucket(int uses, int type)
	{
		this.uses = uses;
		this.type = type;
	}

	/**
	 * @param bucketUsed the bucket was the item used on the patch (null if not known)
	 * @return true if the uses or type changed
	 */
	boolean onMessage(String msg, Boolean bucketUsed)
	{
		Matcher m = CHECK.matcher(msg);
		if (m.find())
		{
			pendingUse = false;
			return set(count(m.group(1)), type(m.group(2)));
		}
		if (EMPTY.matcher(msg).find())
		{
			pendingUse = false;
			return set(0, type);
		}
		m = LEFT.matcher(msg);
		if (m.find())
		{
			pendingUse = false;
			return set(count(m.group(1)), m.group(2) != null ? type(m.group(2)) : type);
		}
		m = FILL_TYPE.matcher(msg);
		if (m.find())
		{
			return set(uses, type(m.group(1)));
		}
		m = FILL_TOTAL.matcher(msg);
		if (m.find())
		{
			return set(count(m.group(1)), type);
		}
		m = TREATED.matcher(msg);
		if (m.find() && Boolean.TRUE.equals(bucketUsed) && uses > 0)
		{
			pendingUse = true;
		}
		return false;
	}

	private static final Pattern DIALOG_USES = Pattern.compile("([\\d,]+) uses");

	/**
	 * The item box shown when you Check the bucket, e.g. "Your bottomless
	 * compost bucket is currently holding 1,204 uses of ultracompost."
	 *
	 * @return true if the uses or type changed
	 */
	boolean onDialog(String text)
	{
		String t = text.replace("<br>", " ");
		if (!t.contains("compost bucket"))
		{
			return false;
		}
		if (t.contains("currently empty") || t.startsWith("You discard"))
		{
			return set(0, type);
		}
		Matcher m = DIALOG_USES.matcher(t);
		int n;
		if (m.find())
		{
			n = count(m.group(1));
		}
		else if (t.contains("one use"))
		{
			n = 1;
		}
		else
		{
			return false;
		}
		return set(n, t.contains("ultracompost") ? 3 : t.contains("supercompost") ? 2 : 1);
	}

	/** End of a game tick: count a use the game didn't report a total for. */
	boolean onTick()
	{
		if (!pendingUse)
		{
			return false;
		}
		pendingUse = false;
		return set(uses - 1, type);
	}

	/**
	 * The leprechaun's bucket varbits: 0 none stored, 1 stored empty, 2-4
	 * compost to ultracompost. Taking it out zeroes them, which says
	 * nothing about the bucket, so that's ignored.
	 */
	boolean onLeprechaun(int storedType, int storedUses)
	{
		if (storedType == 1)
		{
			return set(0, type);
		}
		if (storedType >= 2 && storedUses > 0)
		{
			return set(storedUses, storedType - 1);
		}
		return false;
	}

	/** The filled bucket turned into the empty one: no uses left. */
	boolean onInventory(boolean empty, boolean filled)
	{
		return empty && !filled && uses != 0 && set(0, type);
	}

	private boolean set(int newUses, int newType)
	{
		boolean changed = newUses != uses || newType != type;
		uses = Math.max(newUses, 0);
		type = newType;
		return changed;
	}

	private static int count(String s)
	{
		return s.equals("one") || s.equals("a single") ? 1 : Integer.parseInt(s.replace(",", ""));
	}

	private static int type(String s)
	{
		return s.startsWith("ultra") ? 3 : s.startsWith("super") ? 2 : 1;
	}
}

package com.potionprep;

import static com.potionprep.Recipe.in;
import net.runelite.api.gameval.ItemID;

/** The recipe trees. Nodes are shared, so one super energy node feeds both Super energy and Stamina. */
final class Catalog
{
	private Catalog()
	{
	}

	static String lower(String s)
	{
		return s.isEmpty() ? s : Character.toLowerCase(s.charAt(0)) + s.substring(1);
	}

	static String plural(String s)
	{
		return s.endsWith("y") ? s.substring(0, s.length() - 1) + "ies" : s + "s";
	}

	// --- Tools and bases ---

	static final Node PESTLE = Node.item("Pestle and mortar", ItemID.PESTLE_AND_MORTAR, "General stores");
	static final Node VIAL = Node.item("Vial of water", ItemID.VIAL_WATER, "Fill vials at a sink or fountain, or the GE");
	static final Node COCONUT_MILK = Node.item("Coconut milk", ItemID.VIAL_COCONUT_MILK, "Smash a coconut and fill a vial, or the GE");

	// --- Herbs: grimy -> clean -> unf ---

	static final class Herb
	{
		final Node grimy;
		final Node clean;
		final Node unf;

		Herb(String name, int grimyId, int cleanId, int unfId, int cleanLevel, int unfLevel, double cleanXp)
		{
			grimy = Node.item("Grimy " + lower(name), grimyId, "Farming, drops, or the GE");
			clean = Node.item(name, cleanId, "Farming, drops, or the GE").madeBy(Recipe.clean(grimy, cleanLevel).xp(cleanXp));
			// In game the unf drops "leaf"/"weed": Guam potion (unf), Ranarr potion (unf).
			String shortName = name.replace(" leaf", "").replace("Ranarr weed", "Ranarr");
			unf = Node.item(shortName + " potion (unf)", unfId, null)
				.madeBy(Recipe.mix(unfLevel, 1, "Make %d " + lower(shortName) + " (unf)", in(clean, 1), in(VIAL, 1)));
		}
	}

	static final Herb GUAM = new Herb("Guam leaf", ItemID.UNIDENTIFIED_GUAM, ItemID.GUAM_LEAF, ItemID.GUAMVIAL, 3, 3, 2.5);
	static final Herb MARRENTILL = new Herb("Marrentill", ItemID.UNIDENTIFIED_MARENTILL, ItemID.MARENTILL, ItemID.MARRENTILLVIAL, 5, 5, 3.8);
	static final Herb TARROMIN = new Herb("Tarromin", ItemID.UNIDENTIFIED_TARROMIN, ItemID.TARROMIN, ItemID.TARROMINVIAL, 11, 12, 5);
	static final Herb HARRALANDER = new Herb("Harralander", ItemID.UNIDENTIFIED_HARRALANDER, ItemID.HARRALANDER, ItemID.HARRALANDERVIAL, 20, 22, 6.3);
	static final Herb RANARR = new Herb("Ranarr weed", ItemID.UNIDENTIFIED_RANARR, ItemID.RANARR_WEED, ItemID.RANARRVIAL, 25, 30, 7.5);
	static final Herb TOADFLAX = new Herb("Toadflax", ItemID.UNIDENTIFIED_TOADFLAX, ItemID.TOADFLAX, ItemID.TOADFLAXVIAL, 30, 34, 8);
	static final Herb IRIT = new Herb("Irit leaf", ItemID.UNIDENTIFIED_IRIT, ItemID.IRIT_LEAF, ItemID.IRITVIAL, 40, 45, 8.8);
	static final Herb AVANTOE = new Herb("Avantoe", ItemID.UNIDENTIFIED_AVANTOE, ItemID.AVANTOE, ItemID.AVANTOEVIAL, 48, 50, 10);
	static final Herb KWUARM = new Herb("Kwuarm", ItemID.UNIDENTIFIED_KWUARM, ItemID.KWUARM, ItemID.KWUARMVIAL, 54, 55, 11.3);
	static final Herb SNAPDRAGON = new Herb("Snapdragon", ItemID.UNIDENTIFIED_SNAPDRAGON, ItemID.SNAPDRAGON, ItemID.SNAPDRAGONVIAL, 59, 63, 11.8);
	static final Herb CADANTINE = new Herb("Cadantine", ItemID.UNIDENTIFIED_CADANTINE, ItemID.CADANTINE, ItemID.CADANTINEVIAL, 65, 66, 12.5);
	static final Herb LANTADYME = new Herb("Lantadyme", ItemID.UNIDENTIFIED_LANTADYME, ItemID.LANTADYME, ItemID.LANTADYMEVIAL, 67, 69, 13.1);
	static final Herb DWARF_WEED = new Herb("Dwarf weed", ItemID.UNIDENTIFIED_DWARF_WEED, ItemID.DWARF_WEED, ItemID.DWARFWEEDVIAL, 70, 72, 13.8);
	static final Herb TORSTOL = new Herb("Torstol", ItemID.UNIDENTIFIED_TORSTOL, ItemID.TORSTOL, ItemID.TORSTOLVIAL, 75, 78, 15);

	// --- Secondaries ---

	private static Node crushed(String name, int id, String rawName, int rawId, int yield, String source)
	{
		Node raw = Node.item(rawName, rawId, source);
		return Node.item(name, id, source).madeBy(Recipe.crush(raw, yield, PESTLE));
	}

	static final Node EYE_OF_NEWT = Node.item("Eye of newt", ItemID.EYE_OF_NEWT, "Herblore shops or the GE");
	static final Node UNICORN_HORN_DUST = crushed("Unicorn horn dust", ItemID.UNICORN_HORN_DUST, "Unicorn horn", ItemID.UNICORN_HORN, 1, "Unicorns, or the GE");
	static final Node LIMPWURT_ROOT = Node.item("Limpwurt root", ItemID.LIMPWURT_ROOT, "Hill giants, farming, or the GE");
	static final Node RED_SPIDERS_EGGS = Node.item("Red spiders' eggs", ItemID.RED_SPIDERS_EGGS, "Red spiders, spawns, or the GE");
	static final Node CHOCOLATE_DUST = crushed("Chocolate dust", ItemID.CHOCOLATE_DUST, "Chocolate bar", ItemID.CHOCOLATE_BAR, 1, "Food shops or the GE");
	static final Node WHITE_BERRIES = Node.item("White berries", ItemID.WHITE_BERRIES, "Whiteberry bush, or the GE");
	static final Node TOADS_LEGS = Node.item("Toad's legs", ItemID.TOADS_LEGS, "Gnome shops or the GE");
	static final Node GOAT_HORN_DUST = crushed("Goat horn dust", ItemID.GROUND_DESERT_GOAT_HORN, "Desert goat horn", ItemID.DESERT_GOAT_HORN, 1, "Desert goats, or the GE");
	static final Node SNAPE_GRASS = Node.item("Snape grass", ItemID.SNAPE_GRASS, "Spawns, farming, or the GE");
	static final Node MORT_MYRE_FUNGUS = Node.item("Mort myre fungus", ItemID.MORTMYREMUSHROOM, "Cast Bloom in Mort Myre, or the GE");
	static final Node KEBBIT_TEETH_DUST = crushed("Kebbit teeth dust", ItemID.HUNTINGBEAST_SABRETEETH_DUST, "Kebbit teeth", ItemID.HUNTINGBEAST_SABRETEETH, 1, "Sabre-toothed kebbits, or the GE");
	static final Node DRAGON_SCALE_DUST = crushed("Dragon scale dust", ItemID.DRAGON_SCALE_DUST, "Blue dragon scale", ItemID.BLUE_DRAGON_SCALE, 1, "Blue dragons, or the GE");
	static final Node WINE_OF_ZAMORAK = Node.item("Wine of Zamorak", ItemID.WINE_OF_ZAMORAK, "Telegrab at the Chaos Temple, or the GE");
	static final Node POTATO_CACTUS = Node.item("Potato cactus", ItemID.CACTUS_POTATO, "Kalphite Lair spawns, or the GE");
	static final Node JANGERBERRIES = Node.item("Jangerberries", ItemID.JANGERBERRIES, "Jangerberry bush, or the GE");
	static final Node CRUSHED_NEST = crushed("Crushed nest", ItemID.CRUSHED_BIRD_NEST, "Bird nest", ItemID.BIRD_NEST_EMPTY, 1, "Woodcutting, birdhouses, or the GE");
	static final Node AMYLASE = Node.item("Amylase crystal", ItemID.AMYLASE, "Grace's shop (marks of grace), or the GE");
	// Crushing a lava scale gives 3-6 shards; plan with the minimum.
	static final Node LAVA_SHARD = crushed("Lava scale shard", ItemID.LAVA_SHARD, "Lava scale", ItemID.LAVA_SCALE, 3, "Lava dragons, or the GE");
	static final Node CRUSHED_SUPERIOR_BONES = crushed("Crushed superior dragon bones", ItemID.CRUSHED_DRAGON_BONES, "Superior dragon bones", ItemID.DRAGON_BONES_SUPERIOR, 1, "Wyrms, drakes, hydras, or the GE");
	static final Node MAGIC_ROOTS = Node.item("Magic roots", ItemID.MAGIC_ROOTS, "Magic tree farming, or the GE");
	static final Node ZULRAH_SCALES = Node.item("Zulrah's scales", ItemID.SNAKEBOSS_SCALE, "Zulrah, or the GE");

	// --- Potions ---

	/** unf + secondary = one 3-dose potion. */
	private static Node standard(String name, int level, double xp, Herb herb, Node secondary, int d1, int d2, int d3, int d4)
	{
		return Node.dosed(name, d1, d2, d3, d4)
			.madeBy(Recipe.mix(level, 3, "Mix %d " + plural(lower(name)), in(herb.unf, 1), in(secondary, 1)).xp(xp));
	}

	static final Node ATTACK = standard("Attack potion", 3, 25, GUAM, EYE_OF_NEWT, ItemID._1DOSE1ATTACK, ItemID._2DOSE1ATTACK, ItemID._3DOSE1ATTACK, ItemID._4DOSE1ATTACK);
	static final Node ANTIPOISON = standard("Antipoison", 5, 37.5, MARRENTILL, UNICORN_HORN_DUST, ItemID._1DOSEANTIPOISON, ItemID._2DOSEANTIPOISON, ItemID._3DOSEANTIPOISON, ItemID._4DOSEANTIPOISON);
	static final Node STRENGTH = standard("Strength potion", 12, 50, TARROMIN, LIMPWURT_ROOT, ItemID._1DOSE1STRENGTH, ItemID._2DOSE1STRENGTH, ItemID._3DOSE1STRENGTH, ItemID.STRENGTH4);
	static final Node RESTORE = standard("Restore potion", 22, 62.5, HARRALANDER, RED_SPIDERS_EGGS, ItemID._1DOSESTATRESTORE, ItemID._2DOSESTATRESTORE, ItemID._3DOSESTATRESTORE, ItemID._4DOSESTATRESTORE);
	static final Node ENERGY = standard("Energy potion", 26, 67.5, HARRALANDER, CHOCOLATE_DUST, ItemID._1DOSE1ENERGY, ItemID._2DOSE1ENERGY, ItemID._3DOSE1ENERGY, ItemID._4DOSE1ENERGY);
	static final Node DEFENCE = standard("Defence potion", 30, 75, RANARR, WHITE_BERRIES, ItemID._1DOSE1DEFENSE, ItemID._2DOSE1DEFENSE, ItemID._3DOSE1DEFENSE, ItemID._4DOSE1DEFENSE);
	static final Node AGILITY = standard("Agility potion", 34, 80, TOADFLAX, TOADS_LEGS, ItemID._1DOSE1AGILITY, ItemID._2DOSE1AGILITY, ItemID._3DOSE1AGILITY, ItemID._4DOSE1AGILITY);
