		harvestLabel.setToolTipText("Expected from this run's plantings: Farming level, compost, magic secateurs, "
			+ "Farming cape, diaries and the chance of disease");
		harvestSub.setFont(FontManager.getRunescapeSmallFont());
		harvestSub.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		harvestBox.add(left(harvestLabel));
		harvestBox.add(left(harvestSub));
		harvestBox.setVisible(false);
		// Not stretch(): its text changes, so its height must too.
		harvestBox.setAlignmentX(LEFT_ALIGNMENT);
		add(harvestBox);
		add(Box.createVerticalStrut(6));

		showToggle.setFocusable(false);
		showToggle.setToolTipText("While on, the bank opens filtered to your herb run");
		showToggle.addActionListener(e -> plugin.setShowInBank(showToggle.isSelected()));
		add(stretch(showToggle));
		add(Box.createVerticalStrut(4));
		gearButtons = new GearButtons(plugin, true);
		add(stretch(gearButtons));
		add(Box.createVerticalStrut(10));

		// Guided run: Start, then Skip / Stop while running, and each stop's progress.
		JPanel runButtons = new JPanel(new java.awt.GridLayout(1, 2, 4, 0));
		runButtons.setOpaque(false);
		startRun.setFocusable(false);
		skipStop.setFocusable(false);
		stopRun.setFocusable(false);
		startRun.setToolTipText("Guide the run step by step, like Quest Helper");
		skipStop.setToolTipText("Move on to the next patch");
		startRun.addActionListener(e -> plugin.startRun());
		skipStop.addActionListener(e -> plugin.skipStop());
		stopRun.addActionListener(e -> plugin.stopRun());
		runButtons.add(skipStop);
		runButtons.add(stopRun);
		add(stretch(startRun));
		add(stretch(runButtons));
		runRows.setLayout(new BoxLayout(runRows, BoxLayout.Y_AXIS));
		runRows.setOpaque(false);
		runRows.setAlignmentX(LEFT_ALIGNMENT);
		add(runRows);
		runButtonsPanel = runButtons;
		setRun(null);
		add(Box.createVerticalStrut(10));

		add(left(heading("Patches")));
		for (Patch p : Patch.values())
		{
			add(stretch(patchRow(p)));
			add(Box.createVerticalStrut(2));
		}
		add(Box.createVerticalStrut(8));

		add(left(heading("Supplies")));
		suppliesPanel.setLayout(new BoxLayout(suppliesPanel, BoxLayout.Y_AXIS));
		suppliesPanel.setBackground(ColorScheme.DARK_GRAY_COLOR);
		add(stretch(suppliesPanel));
		add(Box.createVerticalStrut(10));

		add(left(heading("To do")));
		stepsPanel.setLayout(new BoxLayout(stepsPanel, BoxLayout.Y_AXIS));
		stepsPanel.setBackground(ColorScheme.DARK_GRAY_COLOR);
		add(stretch(stepsPanel));
		add(Box.createVerticalStrut(10));

		statusLabel.setFont(FontManager.getRunescapeSmallFont());
		statusLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		add(left(statusLabel));
	}

	void update(FarmPlan plan, FarmPlan.Settings settings, String status, boolean showingInBank, String[] harvest,
		Map<Integer, Integer> seedCounts, int farmingLevel)
	{
		this.seedCounts = seedCounts;
		this.farmingLevel = farmingLevel;
		herb.repaint();
		flower.repaint();
		allotment.repaint();
		harvestBox.setVisible(harvest != null);
		if (harvest != null)
		{
			harvestLabel.setText(wrap(harvest[0]));
			harvestSub.setText(harvest[1] != null ? wrap(harvest[1]) : "");
			harvestSub.setVisible(harvest[1] != null);
		}
		updating = true;
		try
		{
			herb.setSelectedItem(settings.getHerb());
			flower.setSelectedItem(settings.getFlower());
			allotment.setSelectedItem(settings.getAllotment());
			showToggle.setSelected(showingInBank);
			for (Patch p : Patch.values())
			{
				patchBoxes.get(p).setSelected(settings.getPatches().contains(p));
				JLabel t = patchTeleports.get(p);
				t.setText(" ");
				t.setToolTipText(null);
				patchStates.get(p).setText(" ");
				patchStates.get(p).setToolTipText(null);
			}
		}
		finally
		{
			updating = false;
		}

		long now = System.currentTimeMillis() / 1000;
		for (FarmPlan.Stop stop : plan.getStops())
		{
			showState(patchStates.get(stop.getPatch()), stop, now);
			JLabel t = patchTeleports.get(stop.getPatch());
			if (stop.isLocked())
			{
				t.setText(stop.getLockReason());
				t.setForeground(ColorScheme.MEDIUM_GRAY_COLOR);
				t.setToolTipText("Skipped until then");
				continue;
			}
			if (stop.getTeleport() == null)
			{
				continue;
			}
			t.setText(stop.getTeleport().getName() + (stop.isManual() ? "*" : ""));
			t.setForeground(stop.isOwned() ? Color.WHITE : BAD);
			t.setToolTipText("<html>" + (stop.isOwned() ? "" : stop.getProblem() + "<br>")
				+ (stop.getPatch().getTeleports().length > 1
				? "Click to change" + (stop.isManual() ? " (* chosen by you)" : " (best one you can use)")
				: "Only option") + "</html>");
		}

		suppliesPanel.removeAll();
		for (FarmPlan.Supply s : plan.getSupplies())
		{
			suppliesPanel.add(supplyRow(s));
			suppliesPanel.add(Box.createVerticalStrut(2));
		}

		stepsPanel.removeAll();
		for (PotionPlan.Step step : plan.getSteps())
		{
			boolean warn = step.getSeverity() == PotionPlan.Severity.WARNING;
			JLabel l = new JLabel(wrap((warn ? "! " : "") + step.getText()));
			l.setFont(FontManager.getRunescapeSmallFont());
			l.setForeground(warn ? BAD : ACTION);
			l.setBorder(new EmptyBorder(2, 0, 2, 0));
			l.setToolTipText(step.getHint());
			stepsPanel.add(left(l));
		}
		if (plan.getSteps().isEmpty())
		{
			JLabel l = new JLabel("Ready to go");
			l.setFont(FontManager.getRunescapeSmallFont());
			l.setForeground(GOOD);
			stepsPanel.add(left(l));
		}

		statusLabel.setText(wrap(status));
		revalidate();
		repaint();
	}

	/**
	 * @param rows "Stop|state|detail;detail" per stop (state Done / Now / empty), then one footer
	 *             note; null when no run
	 */
	void setRun(String[] rows)
	{
		boolean running = rows != null;
		startRun.setVisible(!running);
		runButtonsPanel.getParent().setVisible(running);
		runRows.removeAll();
		if (running)
		{
			for (int i = 0; i < rows.length - 1; i++)
			{
				String[] parts = rows[i].split("\\|", -1);
				boolean now = parts[1].equals("Now");
				JPanel r = new JPanel(new BorderLayout());
				r.setBackground(now ? ColorScheme.DARK_GRAY_HOVER_COLOR : ColorScheme.DARKER_GRAY_COLOR);
				r.setBorder(new EmptyBorder(2, 6, 2, 6));
				r.setAlignmentX(LEFT_ALIGNMENT);
				JLabel name = new JLabel(parts[0]);
				name.setFont(now ? FontManager.getRunescapeBoldFont() : FontManager.getRunescapeSmallFont());
				name.setForeground(parts[1].equals("Done") ? ColorScheme.MEDIUM_GRAY_COLOR : Color.WHITE);
				JLabel state = new JLabel(parts[1]);
				state.setFont(FontManager.getRunescapeSmallFont());
				state.setForeground(parts[1].equals("Done") ? GOOD : ACTION);
				r.add(name, BorderLayout.WEST);
				r.add(state, BorderLayout.EAST);
				if (now && !parts[2].isEmpty())
				{
					// What to do: the teleport on the way, or each plot's steps at the patch.
					JPanel steps = new JPanel();
					steps.setLayout(new BoxLayout(steps, BoxLayout.Y_AXIS));
					steps.setOpaque(false);
					for (String line : parts[2].split(";"))
					{
						// "Herb: Pick" is a plot and its status; anything else is the way there.
						int colon = line.indexOf(": ");
						boolean plot = false;
						for (HerbRun.PlotType t : HerbRun.PlotType.values())
						{
							plot |= line.startsWith(t.getLabel() + ": ");
						}
						JPanel l = new JPanel(new BorderLayout());
						l.setOpaque(false);
						JLabel left = new JLabel(plot ? line.substring(0, colon) : wrap(line));
						left.setFont(FontManager.getRunescapeSmallFont());
						left.setForeground(plot ? ColorScheme.LIGHT_GRAY_COLOR : ACTION);
						l.add(left, BorderLayout.WEST);
						if (plot)
						{
							String status = line.substring(colon + 2);
							JLabel right = new JLabel(status);
							right.setFont(FontManager.getRunescapeSmallFont());
							right.setForeground(status.equals("Done") ? GOOD : ACTION);
							l.add(right, BorderLayout.EAST);
						}
						steps.add(l);
					}
					r.add(steps, BorderLayout.SOUTH);
				}
				r.setMaximumSize(new Dimension(Integer.MAX_VALUE, r.getPreferredSize().height));
				runRows.add(r);
				runRows.add(Box.createVerticalStrut(1));
			}
			if (rows.length == 1)
			{
				JLabel l = new JLabel("Nothing ready to plant");
				l.setFont(FontManager.getRunescapeSmallFont());
				runRows.add(l);
			}
			String note = rows[rows.length - 1];
			if (!note.isEmpty())
			{
				JLabel l = new JLabel(wrap(note));
				l.setFont(FontManager.getRunescapeSmallFont());
				l.setForeground(note.startsWith("Run done") ? GOOD : ColorScheme.LIGHT_GRAY_COLOR);
				l.setBorder(new EmptyBorder(4, 0, 0, 0));
				runRows.add(l);
			}
		}
		revalidate();
		repaint();
	}

	/** Patch state from Time Tracking: ready, growing (with time left), diseased, dead or empty. */
	private static void showState(JLabel l, FarmPlan.Stop stop, long now)
	{
		PatchStatus st = stop.getStatus();
		if (st == null || stop.isLocked())
		{
			return;
		}
		switch (st.getState())
		{
			case READY:
				l.setText("Ready");
				l.setForeground(GOOD);
				break;
			case GROWING:
				l.setText(FarmPlan.minutes(st.getReadyAt() - now));
				l.setForeground(ColorScheme.MEDIUM_GRAY_COLOR);
				l.setToolTipText("Still growing" + (stop.isGrowing() ? ", left out of this run" : ""));
				break;
			case DISEASED:
				l.setText("Diseased");
				l.setForeground(ACTION);
				break;
			case DEAD:
				l.setText("Dead");
				l.setForeground(BAD);
				break;
			case EMPTY:
				l.setText("Empty");
				l.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
				break;
			default:
				break;
		}
	}

	private JPanel patchRow(Patch p)
	{
		JPanel row = new JPanel(new BorderLayout(4, 0));
		row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		row.setBorder(new EmptyBorder(2, 2, 2, 6));

		JCheckBox box = new JCheckBox(p.getName());
		box.setFont(FontManager.getRunescapeSmallFont());
		box.setOpaque(false);
		box.setFocusable(false);
		box.setToolTipText(describe(p));
		box.addActionListener(e ->
		{
			if (!updating)
			{
				plugin.setPatchEnabled(p, box.isSelected());
			}
		});
		patchBoxes.put(p, box);
		JPanel top = new JPanel(new BorderLayout());
		top.setOpaque(false);
		top.add(box, BorderLayout.CENTER);
		JLabel state = new JLabel(" ");
		state.setFont(FontManager.getRunescapeSmallFont());
		patchStates.put(p, state);
		top.add(state, BorderLayout.EAST);
		row.add(top, BorderLayout.NORTH);

		JLabel tele = new JLabel(" ");
		tele.setFont(FontManager.getRunescapeSmallFont());
		if (p.getTeleports().length > 1)
		{
			tele.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
			tele.addMouseListener(new MouseAdapter()
			{
				@Override
				public void mouseClicked(MouseEvent e)
				{
					plugin.cycleTeleport(p);
				}
			});
		}
		// Teleport names are long, so they go on their own line under the patch.
		tele.setHorizontalAlignment(SwingConstants.LEFT);
		tele.setBorder(new EmptyBorder(0, 22, 2, 0));
		patchTeleports.put(p, tele);
		row.add(tele, BorderLayout.SOUTH);
		return row;
	}

	private static String describe(Patch p)
	{
		StringBuilder sb = new StringBuilder("Herb");
		if (p.isFlower())
		{
			sb.append(", flower");
		}
		if (p.getAllotments() > 0)
		{
			sb.append(", ").append(p.getAllotments()).append(p.getAllotments() == 1 ? " allotment" : " allotments");
		}
		return sb.toString();
	}

	private JPanel supplyRow(FarmPlan.Supply s)
	{
		JPanel p = new JPanel(new BorderLayout(6, 0));
		p.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		p.setBorder(new EmptyBorder(2, 4, 2, 8));
		p.setMaximumSize(new Dimension(Integer.MAX_VALUE, 36));

		JLabel icon = new JLabel();
		icon.setPreferredSize(new Dimension(36, 32));
		icon.setHorizontalAlignment(SwingConstants.CENTER);
		itemManager.getImage(s.getItemId()).addTo(icon);
		p.add(icon, BorderLayout.WEST);

		JLabel name = new JLabel(s.getName());
		name.setFont(FontManager.getRunescapeSmallFont());
		name.setForeground(s.getHave() > 0 ? Color.WHITE : ColorScheme.MEDIUM_GRAY_COLOR);
		p.add(name, BorderLayout.CENTER);

		boolean enough = s.getHave() >= s.getNeed();
		String text = s.getNeed() > 1
			? QuantityFormatter.quantityToStackSize(s.getHave()) + " / " + s.getNeed()
			: enough ? "Have" : "Missing";
		JLabel qty = new JLabel(text);
		qty.setFont(FontManager.getRunescapeSmallFont());
		qty.setForeground(enough ? GOOD : BAD);
		qty.setToolTipText(s.getNeed() > 1 ? "Have / need for this run" : null);
		p.add(qty, BorderLayout.EAST);
		return p;
	}

	private <T> JPanel combo(JComboBox<T> box, String tooltip, Runnable onChange)
	{
		box.setFocusable(false);
		box.setRenderer(new SeedRenderer());
		box.setToolTipText(tooltip);
		box.setPreferredSize(new Dimension(PluginPanel.PANEL_WIDTH - 20, 25));
		box.addActionListener(e ->
		{
			if (!updating)
			{
				onChange.run();
			}
		});
		JPanel p = new JPanel(new BorderLayout());
		p.setOpaque(false);
		p.add(box, BorderLayout.CENTER);
		return p;
	}

	/** "Ranarr  918" with the count of seeds you have, or "Lv 85" in red if your Farming is too low. */
	private class SeedRenderer extends javax.swing.DefaultListCellRenderer
	{
		@Override
		public java.awt.Component getListCellRendererComponent(javax.swing.JList<?> list, Object value, int index,
			boolean selected, boolean focused)
		{
			JLabel l = (JLabel) super.getListCellRendererComponent(list, value, index, selected, focused);
			if (!(value instanceof Farm.Seed) || ((Farm.Seed) value).getSeedId() == -1)
			{
				return l;
			}
			Farm.Seed seed = (Farm.Seed) value;
			String right;
			String color;
			if (farmingLevel > 0 && farmingLevel < seed.getLevel())
			{
				right = "Lv " + seed.getLevel();
				color = "#E05A5A";
			}
			else
			{
				int n = seedCounts.getOrDefault(seed.getSeedId(), 0);
				right = QuantityFormatter.quantityToStackSize(n);
				color = n > 0 ? "#5FBF5F" : "#808080";
			}
			l.setText("<html>" + seed.getName() + "&nbsp;&nbsp;<font color='" + color + "'>" + right + "</font></html>");
			l.setToolTipText("Needs " + seed.getLevel() + " Farming");
			return l;
		}
	}

	private static JLabel heading(String text)
	{
		JLabel l = new JLabel(text);
		l.setFont(FontManager.getRunescapeSmallFont());
		l.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		l.setBorder(BorderFactory.createEmptyBorder(0, 0, 4, 0));
		return l;
	}

	private static String wrap(String text)
	{
		return "<html><body style='width:165px'>" + text + "</body></html>";
	}

	private static JPanel left(java.awt.Component c)
	{
		JPanel p = new JPanel(new BorderLayout());
		p.setOpaque(false);
		p.add(c, BorderLayout.WEST);
		p.setAlignmentX(LEFT_ALIGNMENT);
		p.setMaximumSize(new Dimension(Integer.MAX_VALUE, c.getPreferredSize().height + 400));
		return p;
	}

	private static JPanel stretch(java.awt.Component c)
	{
		JPanel p = new JPanel(new BorderLayout());
		p.setOpaque(false);
		p.add(c, BorderLayout.CENTER);
		p.setAlignmentX(LEFT_ALIGNMENT);
		p.setMaximumSize(new Dimension(Integer.MAX_VALUE, c.getPreferredSize().height));
		return p;
	}
}

package com.potionprep;

import java.util.ArrayList;
import java.util.List;
import java.util.function.Predicate;
import net.runelite.api.gameval.ItemID;

/**
 * Herblore gear, laid out in the bank like the worn-equipment tab:
 * <pre>
 *        head
 *  cape  neck
 *        body
 *        legs
 *  hands
 * </pre>
 * Only gear the player owns is shown; the variant in the bank wins (e.g.
 * either state of the prescription goggles).
 */
final class Gear
{
	static final int WIDTH = 3;

	private enum Slot
	{
		HEAD(0, 1, ItemID.MM_ALCHEMIST_HAT, ItemID.MM_ALCHEMIST_HAT_ALT),
		CAPE(1, 0, ItemID.SKILLCAPE_HERBLORE_TRIMMED, ItemID.SKILLCAPE_HERBLORE),
		NECK(1, 1, ItemID.AMULET_OF_CHEMISTRY_IMBUED_CHARGED, ItemID.AMULET_OF_CHEMISTRY),
		BODY(2, 1, ItemID.MM_ALCHEMIST_BODY, ItemID.MM_ALCHEMIST_BODY_ALT),
		LEGS(3, 1, ItemID.MM_ALCHEMIST_LEGS, ItemID.MM_ALCHEMIST_LEGS_ALT),
		HANDS(4, 0, ItemID.MM_ALCHEMIST_GLOVES);

		final int row;
		final int col;
		final int[] ids; // best first

		Slot(int row, int col, int... ids)
		{
			this.row = row;
			this.col = col;
			this.ids = ids;
		}
	}

	private Gear()
	{
	}

	/** Every gear id, for clearing old state. */
	static List<Integer> allIds()
	{
		List<Integer> out = new ArrayList<>();
		for (Slot s : Slot.values())
		{
			for (int id : s.ids)
			{
				out.add(id);
			}
		}
		return out;
	}

	/**
	 * A slot is shown when the player owns gear for it anywhere: in the bank,
	 * inventory, worn, or as a bank placeholder. If the item isn't in the bank,
	 * Bank Tags draws it faded, like a placeholder.
	 *
	 * @param inBank item id is in the bank (quantity > 0)
	 * @param owned  item id is worn, in the inventory, or a bank placeholder
	 * @return rows of {@link Gear#WIDTH} ids (-1 = empty), empty rows dropped.
	 */
	static List<int[]> rows(Predicate<Integer> inBank, Predicate<Integer> owned)
	{
		int[][] grid = new int[5][WIDTH];
		for (int[] r : grid)
		{
			java.util.Arrays.fill(r, -1);
		}
		for (Slot s : Slot.values())
		{
			grid[s.row][s.col] = pick(s.ids, inBank);
			if (grid[s.row][s.col] == -1)
			{
				grid[s.row][s.col] = pick(s.ids, owned);
			}
		}
		List<int[]> out = new ArrayList<>();
		for (int[] r : grid)
		{
			if (r[0] != -1 || r[1] != -1 || r[2] != -1)
			{
				out.add(r);
			}
		}
		return out;
	}

	private static int pick(int[] ids, Predicate<Integer> test)
	{
		for (int id : ids)
		{
			if (test.test(id))
			{
				return id;
			}
		}
		return -1;
	}

	/**
	 * First bank row the gear block can start on without overlapping the
	 * potion rows' occupied cells (left {@link Gear#WIDTH} columns).
	 */
	static int startRow(List<boolean[]> occupied, List<int[]> gear)
	{
		for (int g = 0; ; g++)
		{
			boolean clash = false;
			for (int r = 0; r < gear.size() && !clash; r++)
			{
				int row = g + r;
				if (row >= occupied.size())
				{
					break;
				}
				for (int c = 0; c < WIDTH; c++)
				{
					clash |= gear.get(r)[c] != -1 && occupied.get(row)[c];
				}
			}
			if (!clash)
			{
				return g;
			}
		}
	}

	/** Equipment slot index (EquipmentInventorySlot) to {row, col} in the equipment-tab shape. */
	private static final int[][] SLOT_POS = {
		{0, 1}, // 0 head
		{1, 0}, // 1 cape
		{1, 1}, // 2 neck
		{2, 0}, // 3 weapon
		{2, 1}, // 4 body
		{2, 2}, // 5 shield
		null, // 6 (arms, unused)
		{3, 1}, // 7 legs
		null, // 8 (hair, unused)
		{4, 0}, // 9 gloves
		{4, 1}, // 10 boots
		null, // 11 (jaw, unused)
		{4, 2}, // 12 ring
		{1, 2}, // 13 ammo
	};

	/**
	 * Saved worn gear laid out like the equipment tab.
	 *
	 * @param slots item id per equipment slot index, -1 for empty
	 * @return rows of {@link Gear#WIDTH} ids (-1 = empty), empty rows dropped
	 */
	static List<int[]> fromSlots(int[] slots)
	{
		int[][] grid = new int[5][WIDTH];
		for (int[] r : grid)
		{
			java.util.Arrays.fill(r, -1);
		}
		for (int i = 0; i < slots.length && i < SLOT_POS.length; i++)
		{
			if (SLOT_POS[i] != null && slots[i] > 0)
			{
				grid[SLOT_POS[i][0]][SLOT_POS[i][1]] = slots[i];
			}
		}
		List<int[]> out = new ArrayList<>();
		for (int[] r : grid)
		{
			if (r[0] != -1 || r[1] != -1 || r[2] != -1)
			{
				out.add(r);
			}
		}
		return out;
	}
}

package com.potionprep;

import java.awt.BorderLayout;
import javax.swing.JButton;
import javax.swing.JPanel;

/** "Save worn gear" / "Clear": remember what you're wearing as this mode's gear. */
class GearButtons extends JPanel
{
	private final JButton save = new JButton("Save worn gear");
	private final JButton clear = new JButton("Clear");

	GearButtons(PotionPrepPlugin plugin, boolean farm)
	{
		super(new BorderLayout(4, 0));
		setOpaque(false);
		save.setFocusable(false);
		clear.setFocusable(false);
		save.setToolTipText("<html>Lay out what you're wearing now on the left of the bank view,<br>"
			+ "like the equipment tab. Pieces you're wearing show faded.</html>");
		clear.setToolTipText("Forget the saved gear");
		save.addActionListener(e -> plugin.saveWornGear(farm));
		clear.addActionListener(e -> plugin.clearGear(farm));
		add(save, BorderLayout.CENTER);
		add(clear, BorderLayout.EAST);
		setSaved(false);
	}

	void setSaved(boolean saved)
	{
		save.setText(saved ? "Update worn gear" : "Save worn gear");
		clear.setVisible(saved);
	}
}

package com.potionprep;

import com.potionprep.Farm.Patch;
import com.potionprep.Farm.Teleport;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Locale;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import lombok.Getter;

/**
 * A herb run in progress, Quest Helper style: one stop at a time, each with
 * the plots to plant there. A plot is done once it's planted and, if you
 * brought compost, composted. Progress comes from the game's own messages.
 */
@Getter
public class HerbRun
{
	public enum PlotType
	{
		HERB("Herb"), FLOWER("Flower"), ALLOTMENT("Allotment");

		@Getter
		private final String label;

		PlotType(String label)
		{
			this.label = label;
		}
	}

	@Getter
	public static class Plot
	{
		private final PlotType type;
		private final String seed;
		private boolean planted;
		private boolean composted;
		/** For the herb plot: what the patch needs right now (read live at the patch), or null. */
		private PatchStatus.Task task;
		/** Not enough seeds with you to plant it: it doesn't hold up the stop. */
		private boolean noSeeds;

		/** Seeds one planting uses. */
		int seedsPer()
		{
			return type == PlotType.ALLOTMENT ? Farm.SEEDS_PER_ALLOTMENT : 1;
		}

		Plot(PlotType type, String seed)
		{
			this.type = type;
			this.seed = seed;
		}
	}

	@Getter
	public static class Stop
	{
		private final Patch patch;
		/** Shown name, e.g. "Farming Guild allotments". */
		private final String name;
		/** Where the plots are, for the route and hint arrow. */
		private final net.runelite.api.coords.WorldPoint point;
		/** How to get here; null for a short walk from the stop before. */
		private final Teleport teleport;
		/** Item for the teleport, -1 for spells, staff-free fairy rings and walks. */
		private final int itemId;
		private final List<Plot> plots;
		/** You've been here this run. */
		private boolean visited;

		Stop(Patch patch, String name, net.runelite.api.coords.WorldPoint point, Teleport teleport, int itemId, List<Plot> plots)
		{
			this.patch = patch;
			this.name = name;
			this.point = point;
			this.teleport = teleport;
			this.itemId = itemId;
			this.plots = plots;
		}

		boolean hasHerb()
		{
			return !plots.isEmpty() && plots.get(0).type == PlotType.HERB;
		}

		boolean done(boolean compost)
		{
			for (Plot p : plots)
			{
				if (p.noSeeds && !p.planted)
				{
					continue;
				}
				if (!p.planted || compost && !p.composted)
				{
					return false;
				}
			}
			return true;
		}
	}

	// "You plant a Ranarr seed in the herb patch." / "You plant 3 snape grass seeds in the allotment."
	private static final Pattern PLANT = Pattern.compile("You plant .+ in the (herb patch|flower patch|allotment)",
		Pattern.CASE_INSENSITIVE);
	// "You treat the herb patch with ultracompost." / "This allotment has already been treated with compost."
	// / "The herb patch has been treated with supercompost." (Fertile Soil). Before or after planting.
	private static final Pattern COMPOST = Pattern.compile(
		"(?:You treat the|This|The) (herb patch|flower patch|allotment)(?: with| has (?:already )?been (?:treated|fertilised) with) (?:ultra|super|)compost",
		Pattern.CASE_INSENSITIVE);

	private final List<Stop> stops;
	/** You have compost (carried or at the leprechaun), so plots also need composting. Turns off if you run out. */
	private boolean compost;
	private final long startedAt;
	private int index;
	/** Stops skipped rather than done. */
	private int skipped;

	HerbRun(List<Stop> stops, boolean compost, long startedAt)
	{
		this.stops = Collections.unmodifiableList(stops);
		this.compost = compost;
		this.startedAt = startedAt;
	}

	/** Build a run from a plan: every patch on it, in order, with its plots. */
	static HerbRun from(FarmPlan plan, FarmPlan.Settings settings, long now)
	{
		// Flowers and allotments only while the seeds last, in run order.
		int flowerSeeds = seedsHave(plan, settings.getFlower().getSeedId());
		int allotSeeds = seedsHave(plan, settings.getAllotment().getSeedId());
		List<Stop> stops = new ArrayList<>();
		for (FarmPlan.Stop st : plan.getStops())
		{
			if (st.isLocked() || st.isGrowing())
			{
				continue;
			}
			Patch p = st.getPatch();
			List<Plot> plots = new ArrayList<>();
			plots.add(new Plot(PlotType.HERB, settings.getHerb().getName() + " seed"));
			List<Plot> others = new ArrayList<>();
			if (p.isFlower() && settings.getFlower() != Farm.FlowerSeed.NONE && flowerSeeds >= 1)
			{
				flowerSeeds--;
				others.add(new Plot(PlotType.FLOWER, settings.getFlower().getName() + " seed"));
			}
			if (settings.getAllotment() != Farm.AllotmentSeed.NONE)
			{
				for (int i = 0; i < p.getAllotments() && allotSeeds >= Farm.SEEDS_PER_ALLOTMENT; i++)
				{
					allotSeeds -= Farm.SEEDS_PER_ALLOTMENT;
					others.add(new Plot(PlotType.ALLOTMENT, settings.getAllotment().getName() + " seeds"));
				}
			}
			net.runelite.api.coords.WorldPoint apart = PatchPlaces.otherPlots(p);
			if (apart != null && !others.isEmpty())
			{
				// The flower and allotments here are a walk from the herb patch: their own stop.
				stops.add(new Stop(p, p.getName(), PatchPlaces.point(p), st.getTeleport(), st.getItemId(), plots));
				stops.add(new Stop(p, p.getName() + " allotments", apart, null, -1, others));
			}
			else
			{
				plots.addAll(others);
				stops.add(new Stop(p, p.getName(), PatchPlaces.point(p), st.getTeleport(), st.getItemId(), plots));
			}
		}
		boolean compost = plan.getSupplies().stream().anyMatch(s -> isCompost(s.getItemId()) && s.getHave() > 0);
		return new HerbRun(stops, compost, now);
	}

	/** Seeds you have of a kind (bank, inventory, seed vault), from the plan. */
	private static int seedsHave(FarmPlan plan, int seedId)
	{
		if (seedId == -1)
		{
			return 0;
		}
		return plan.getSupplies().stream().filter(s -> s.getItemId() == seedId).mapToInt(FarmPlan.Supply::getHave)
			.findFirst().orElse(0);
	}

	private static boolean isCompost(int id)
	{
		if (id == Farm.BOTTOMLESS_BUCKET)
		{
			return true;
		}
		for (int c : Farm.COMPOST)
		{
			if (c == id)
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * Whether you have compost to hand: carried, or stored with the tool
	 * leprechaun (there's one at every patch). Running out mid-run stops plots
	 * waiting for it, so the run carries on with planting only.
	 *
	 * @return true if anything changed
	 */
	boolean setCompostCarried(boolean carried)
	{
		if (!compost || carried)
		{
			return false;
		}
		compost = false;
		Stop stop = current();
		if (stop != null && stop.done(false))
		{
			index++;
		}
		return true;
	}

	/**
	 * Seeds you're carrying, by plot type. Plots there aren't enough seeds
	 * for are marked "No seeds" so they don't hold up the stop.
	 *
	 * @return true if anything changed
	 */
	boolean setSeedsCarried(java.util.Map<PlotType, Integer> carried)
	{
		Stop stop = current();
		if (stop == null)
		{
			return false;
		}
		java.util.Map<PlotType, Integer> left = new java.util.EnumMap<>(PlotType.class);
		left.putAll(carried);
		boolean changed = false;
		for (Plot p : stop.plots)
		{
			if (p.planted)
			{
				continue;
			}
			int have = left.getOrDefault(p.type, 0);
			boolean none = have < p.seedsPer();
			if (!none)
			{
				left.put(p.type, have - p.seedsPer());
			}
			changed |= p.noSeeds != none;
			p.noSeeds = none;
		}
		if (changed && stop.done(compost))
		{
			index++;
		}
		return changed;
	}

	/**
	 * Where you are relative to the current stop. Arriving marks it visited;
	 * leaving a visited stop once its herb is planted (or can't be) moves the
	 * run on, so plots you chose not to do don't hold it up.
	 *
	 * @return true if the run moved on
	 */
	boolean onPosition(boolean atStop)
	{
		Stop stop = current();
		if (stop == null)
		{
			return false;
		}
		if (atStop)
		{
			stop.visited = true;
			return false;
		}
		if (!stop.visited)
		{
			return false;
		}
		Plot first = stop.plots.get(0);
		if (first.planted || first.noSeeds || !stop.hasHerb())
		{
			index++;
			return true;
		}
		return false;
	}

	/** The stop in hand, or null when the run is over. */
	public Stop current()
	{
		return index < stops.size() ? stops.get(index) : null;
	}

	public boolean finished()
	{
		return index >= stops.size();
	}

	public void skip()
	{
		if (!finished())
		{
			index++;
			skipped++;
		}
	}

	/**
	 * A game message while at the current stop. Credits the plot it names;
	 * moves on when the stop is done.
	 *
	 * @return true if anything changed
	 */
	boolean onMessage(String message)
	{
		Stop stop = current();
		if (stop == null)
		{
			return false;
		}
		boolean changed = false;
		Matcher m = PLANT.matcher(message);
		if (m.find())
		{
			changed = credit(stop, type(m.group(1)), true);
		}
		m = COMPOST.matcher(message);
		if (m.find())
		{
			changed |= credit(stop, type(m.group(1)), false);
		}
		if (changed && stop.done(compost))
		{
			index++;
		}
		return changed;
	}

	/**
	 * The herb patch's live state at the current stop. Growing means it's
	 * planted, so this also catches plantings without a chat message.
	 *
	 * @return true if anything changed
	 */
	boolean onHerbState(PatchStatus.Task task)
	{
		Stop stop = current();
		if (stop == null || !stop.hasHerb())
		{
			return false;
		}
		Plot herb = stop.plots.get(0);
		boolean changed = herb.task != task;
		herb.task = task;
		if (task == PatchStatus.Task.GROWING && !herb.planted)
		{
			herb.planted = true;
			changed = true;
		}
		if (changed && stop.done(compost))
		{
			index++;
		}
		return changed;
	}

	/** Marks the first plot of this type still missing that step. */
	private static boolean credit(Stop stop, PlotType type, boolean planted)
	{
		for (Plot p : stop.plots)
		{
			if (p.type != type)
			{
				continue;
			}
			if (planted && !p.planted)
			{
				p.planted = true;
				return true;
			}
			if (!planted && !p.composted)
			{
				p.composted = true;
				return true;
			}
		}
		return false;
	}

	private static PlotType type(String place)
	{
		switch (place.toLowerCase(Locale.ROOT))
		{
			case "flower patch":
				return PlotType.FLOWER;
			case "allotment":
				return PlotType.ALLOTMENT;
			default:
				return PlotType.HERB;
		}
	}

	/** A word or two for a plot: Pick, Clear, Cure, Rake, then what's left of planting and composting, or Done. */
	static String status(Plot p, boolean compost)
	{
		if (p.noSeeds && !p.planted)
		{
			return "No seeds";
		}
		if (!p.planted && p.task != null)
		{
			switch (p.task)
			{
				case PICK:
					return "Pick";
				case CLEAR:
					return "Clear";
				case CURE:
					return "Cure";
				case RAKE:
					return "Rake";
				default:
					break;
			}
		}
		// Compost and seed go on in either order.
		boolean needsCompost = compost && !p.composted;
		if (!p.planted)
		{
			return needsCompost ? "Plant + compost" : "Plant";
		}
		return needsCompost ? "Compost" : "Done";
	}

	/** What's left at a plot, e.g. "pick, compost, plant ranarr seed". */
	static String todo(Plot p, boolean compost)
	{
		List<String> left = new ArrayList<>();
		if (p.task != null && p.task != PatchStatus.Task.PLANT && p.task != PatchStatus.Task.GROWING && !p.planted)
		{
			left.add(Catalog.lower(p.task.getText()));
		}
		if (compost && !p.composted)
		{
			left.add("compost");
		}
		if (!p.planted)
		{
			left.add("plant " + Catalog.lower(p.seed));
		}
		return String.join(", ", left);
	}
}

package com.potionprep;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.geom.Path2D;
import java.awt.image.BufferedImage;
import net.runelite.api.Client;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * Minimap marker for the run's next patch: a pin when it's on the minimap,
 * otherwise an arrow at the minimap's edge pointing the way.
 */
class NavOverlay extends Overlay
{
	static final Color FILL = new Color(30, 147, 255);
	static final Color EDGE = new Color(22, 43, 83);

	/** The game's own farming patch map icon and yellow guide arrow, so it looks native. */
	static final int FARMING_ICON = 1501; // SpriteID.MAP_ICON_FARMING_PATCH
	private static final int GUIDE_ARROW = 441; // SpriteID.MINIMAP_GUIDE_ARROW_YELLOW (points down)

	private final Client client;
	private final net.runelite.client.game.SpriteManager sprites;
	private volatile WorldPoint target;
	/** The guide arrow turned to 64 directions, made once the sprite has loaded. */
	private BufferedImage[] arrows;

	NavOverlay(Client client, net.runelite.client.game.SpriteManager sprites)
	{
		this.client = client;
		this.sprites = sprites;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	void set(WorldPoint target)
	{
		this.target = target;
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		WorldPoint dest = target;
		if (dest == null || client.getLocalPlayer() == null)
		{
			return null;
		}
		Widget minimap = client.getWidget(!client.isResized() ? InterfaceID.Toplevel.MINIMAP
			: client.getVarbitValue(VarbitID.RESIZABLE_STONE_ARRANGEMENT) == 1 ? InterfaceID.ToplevelPreEoc.MINIMAP
			: InterfaceID.ToplevelOsrsStretch.MINIMAP);
		if (minimap == null || minimap.isHidden())
		{
			return null;
		}
		int radius = Math.min(minimap.getWidth(), minimap.getHeight()) / 2 - 19;
		if (radius <= 0)
		{
			return null;
		}
		WorldPoint me = client.getLocalPlayer().getWorldLocation();
		double dx = dest.getX() - me.getX();
		double dy = dest.getY() - me.getY();
		// Rotate into minimap space (it turns with the camera) and scale by its zoom.
		double angle = (client.getCameraYawTarget() & 0x3fff) * Math.PI / 8192;
		double zoom = client.getMinimapZoom();
		double x = (Math.cos(angle) * dx + Math.sin(angle) * dy) * zoom;
		double y = (Math.sin(angle) * dx - Math.cos(angle) * dy) * zoom;
		double len = Math.hypot(x, y);
		boolean inside = len <= radius;
		if (!inside)
		{
			x *= radius / len;
			y *= radius / len;
		}
		net.runelite.api.Point origin = minimap.getCanvasLocation();
		int cx = origin.getX() + minimap.getWidth() / 2 + (int) Math.round(x);
		int cy = origin.getY() + minimap.getHeight() / 2 + (int) Math.round(y);
		BufferedImage img = inside ? sprites.getSprite(FARMING_ICON, 0) : gameArrow(Math.atan2(y, x));
		if (img == null)
		{
			// Sprites not loaded yet: fall back to our own art for this frame.
			img = inside ? PIN : arrow(Math.atan2(y, x));
		}
		g.drawImage(img, cx - img.getWidth() / 2, cy - img.getHeight() / 2, null);
		return null;
	}

	static final Color HIGHLIGHT = new Color(135, 237, 255);
	static final BufferedImage PIN = pin();
	/** Arrows pre-drawn in 64 directions, so nothing is drawn per frame. */
	private static final BufferedImage[] ARROWS = new BufferedImage[64];

	static
	{
		for (int i = 0; i < ARROWS.length; i++)
		{
			ARROWS[i] = drawArrow(i * Math.PI * 2 / ARROWS.length);
		}
	}

	/** The game's yellow guide arrow, turned to point along {@code angle}. */
	private BufferedImage gameArrow(double angle)
	{
		if (arrows == null)
		{
			BufferedImage base = sprites.getSprite(GUIDE_ARROW, 0);
			if (base == null)
			{
				return null;
			}
			arrows = new BufferedImage[64];
			int size = Math.max(base.getWidth(), base.getHeight()) + 4;
			for (int i = 0; i < arrows.length; i++)
			{
				BufferedImage img = new BufferedImage(size, size, BufferedImage.TYPE_INT_ARGB);
				Graphics2D g = img.createGraphics();
				g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
				g.translate(size / 2.0, size / 2.0);
				// The sprite points down (+y); turn it to point along the angle.
				g.rotate(i * Math.PI * 2 / arrows.length - Math.PI / 2);
				g.drawImage(base, -base.getWidth() / 2, -base.getHeight() / 2, null);
				g.dispose();
				arrows[i] = img;
			}
		}
		return arrows[Math.floorMod((int) Math.round(angle * arrows.length / (2 * Math.PI)), arrows.length)];
	}

	private static BufferedImage arrow(double angle)
	{
		return ARROWS[Math.floorMod((int) Math.round(angle * ARROWS.length / (2 * Math.PI)), ARROWS.length)];
	}

	private static BufferedImage pin()
	{
		BufferedImage img = new BufferedImage(28, 28, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = img.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setColor(EDGE);
		g.fillOval(3, 3, 22, 22);
		g.setColor(FILL);
		g.fillOval(5, 5, 18, 18);
		g.setColor(HIGHLIGHT);
		g.setStroke(new BasicStroke(2));
		g.drawOval(5, 5, 18, 18);
		g.setColor(Color.WHITE);
		g.fillOval(11, 11, 6, 6);
		g.dispose();
		return img;
	}

	/** Arrowhead: thick dark outline, blue fill, light inner edge. */
	private static BufferedImage drawArrow(double angle)
	{
		BufferedImage img = new BufferedImage(28, 28, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = img.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.translate(14, 14);
		g.rotate(angle);
		Path2D shape = new Path2D.Double();
		shape.moveTo(11, 0);
		shape.lineTo(-9, -9);
		shape.lineTo(-4, 0);
		shape.lineTo(-9, 9);
		shape.closePath();
		g.setColor(EDGE);
		g.setStroke(new BasicStroke(4));
		g.draw(shape);
		g.setColor(FILL);
		g.fill(shape);
		g.setColor(HIGHLIGHT);
		g.setStroke(new BasicStroke(1.5f));
		g.draw(shape);
		g.dispose();
		return img;
	}
}

package com.potionprep;

import java.util.Map;
import lombok.Getter;

/**
 * One item in a recipe tree. Potions are "dosed": counted in doses across
 * their 1-4 dose variants, since doses can be decanted freely.
 */
@Getter
public final class Node
{
	private final String name;
	/** Main item id; for dosed items the 4-dose id. */
	private final int id;
	/** Ids indexed by dose - 1, or null for non-dosed items. */
	private final int[] doseIds;
	/** Where to get it when it cannot be made, or null. */
	private final String source;
	private Recipe recipe;

	private Node(String name, int id, int[] doseIds, String source)
	{
		this.name = name;
		this.id = id;
		this.doseIds = doseIds;
		this.source = source;
	}

	static Node item(String name, int id, String source)
	{
		return new Node(name, id, null, source);
	}

	static Node dosed(String name, int d1, int d2, int d3, int d4)
	{
		return new Node(name, d4, new int[]{d1, d2, d3, d4}, null);
	}

	Node madeBy(Recipe recipe)
	{
		this.recipe = recipe;
		return this;
	}

	public boolean isDosed()
	{
		return doseIds != null;
	}

	/** Ids for this item's bank row: (1) (2) (3) (4) left to right for potions. */
	public int[] rowIds()
	{
		return isDosed() ? doseIds.clone() : new int[]{id};
	}

	/** Units held: item count, or total doses. */
	public int count(Map<Integer, Integer> counts)
	{
		if (!isDosed())
		{
			return counts.getOrDefault(id, 0);
		}
		int doses = 0;
		for (int d = 0; d < 4; d++)
		{
			doses += (d + 1) * counts.getOrDefault(doseIds[d], 0);
		}
		return doses;
	}
}

package com.potionprep;

import com.potionprep.Farm.Patch;
import java.util.EnumMap;
import java.util.Map;
import net.runelite.api.coords.WorldPoint;

/** Where each herb patch is, for the run's hint arrow and "you're there" check. */
final class PatchPlaces
{
	private static final Map<Patch, WorldPoint> POINTS = new EnumMap<>(Patch.class);

	static
	{
		POINTS.put(Patch.FARMING_GUILD, new WorldPoint(1238, 3726, 0));
		POINTS.put(Patch.HOSIDIUS, new WorldPoint(1738, 3550, 0));
		POINTS.put(Patch.CIVITAS, new WorldPoint(1581, 3094, 0));
		POINTS.put(Patch.ARDOUGNE, new WorldPoint(2670, 3374, 0));
		POINTS.put(Patch.CATHERBY, new WorldPoint(2813, 3463, 0));
		POINTS.put(Patch.FALADOR, new WorldPoint(3058, 3311, 0));
		POINTS.put(Patch.MORYTANIA, new WorldPoint(3605, 3529, 0));
		POINTS.put(Patch.TROLL_STRONGHOLD, new WorldPoint(2826, 3694, 0));
		POINTS.put(Patch.WEISS, new WorldPoint(2847, 3931, 0));
		POINTS.put(Patch.HARMONY, new WorldPoint(3789, 2837, 0));
	}

	/** Where a location's flower and allotments are, when they aren't by the herb patch; else null. */
	static WorldPoint otherPlots(Patch p)
	{
		return p == Patch.FARMING_GUILD ? new WorldPoint(1266, 3730, 0) : null;
	}

	/** Close enough to count as being at the plots (the guild's two spots are 28 tiles apart). */
	private static final int NEAR = 25;

	private PatchPlaces()
	{
	}

	static WorldPoint point(Patch p)
	{
		return POINTS.get(p);
	}

	static boolean near(WorldPoint at, WorldPoint player)
	{
		return at != null && player != null && at.getPlane() == player.getPlane() && at.distanceTo2D(player) <= NEAR;
	}
}

package com.potionprep;

import com.potionprep.Farm.Patch;
import java.util.EnumMap;
import java.util.Map;
import lombok.Value;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.config.ConfigManager;

/**
 * What each herb patch was doing when RuneLite's Time Tracking plugin last
 * saw it, and when a growing crop will be ready. Time Tracking stores each
 * patch's varbit value and when it was seen under the "timetracking" config
 * group as "&lt;region&gt;.&lt;varbit&gt;" = "value:epochSeconds".
 *
 * Value ranges and the growth-tick maths follow Time Tracking's
 * PatchImplementation.HERB and FarmingTracker.getTickTime.
 */
@Value
public class PatchStatus
{
	public enum State
	{
		READY, GROWING, DISEASED, DEAD, EMPTY, UNKNOWN
	}

	State state;
	/** When a growing crop is ready, epoch seconds; 0 otherwise. */
	long readyAt;

	/** Herbs grow in 20 minute ticks over 5 stages. */
	static final int TICK_MINUTES = 20;
	static final int STAGES = 5;

	/** Start of each herb's 4 growing values (guam .. torstol, huasca, goutweed). */
	private static final int[] GROWING_STARTS = {4, 11, 18, 25, 32, 39, 46, 53, 60, 68, 75, 82, 89, 96, 103, 192};

	/** The state a herb patch varbit value means, ignoring time. */
	static State decode(int value)
	{
		for (int start : GROWING_STARTS)
		{
			if (value >= start && value <= start + 3)
			{
				return State.GROWING;
			}
			// The 3 values after a crop's growing range are it being harvestable.
			int harvestEnd = start == 192 ? start + 5 : start + 6;
			if (value > start + 3 && value <= harvestEnd)
			{
				return State.READY;
			}
		}
		if (value >= 128 && value <= 169 || value >= 173 && value <= 175 || value >= 198 && value <= 200)
		{
			return State.DISEASED;
		}
		if (value >= 170 && value <= 172 || value >= 201 && value <= 203)
		{
			return State.DEAD;
		}
		if (value >= 0 && value <= 3 || value == 67 || value >= 176 && value <= 191
			|| value >= 204 && value <= 219 || value >= 221 && value <= 255)
		{
			return State.EMPTY;
		}
		return State.UNKNOWN;
	}

	/**
	 * @param seen      when the value was seen, epoch seconds
	 * @param offsetMin Time Tracking's learnt farming tick offset, or null
	 * @param precision how precisely that offset is known (minutes), or null
	 * @param now       epoch seconds
	 */
	static PatchStatus of(int value, long seen, Integer offsetMin, Integer precision, long now)
	{
		State state = decode(value);
		if (state != State.GROWING)
		{
			return new PatchStatus(state, 0);
		}
		int stage = -1;
		for (int start : GROWING_STARTS)
		{
			if (value >= start && value <= start + 3)
			{
				stage = value - start;
			}
		}
		long readyAt = tickTime(STAGES - 1 - stage, seen, offsetMin, precision);
		return readyAt <= now ? new PatchStatus(State.READY, 0) : new PatchStatus(State.GROWING, readyAt);
	}

	/** The growth tick {@code ticks} ticks after the one {@code at} falls in. */
	static long tickTime(int ticks, long at, Integer offsetMin, Integer precision)
	{
		long offset = 0;
		if (offsetMin != null && precision != null && (precision >= TICK_MINUTES || precision >= 40))
		{
			offset = (offsetMin % TICK_MINUTES) * 60L;
		}
		long shifted = at + offset;
		long tick = shifted - shifted % (TICK_MINUTES * 60L);
		return tick + (long) ticks * TICK_MINUTES * 60 - offset;
	}

	/** What to do at a herb patch right now, from its live varbit value. */
	public enum Task
	{
		PICK("Pick the herbs"),
		CLEAR("Clear the dead herbs (spade)"),
		CURE("Cure (plant cure) or clear it"),
		RAKE("Rake the weeds"),
		PLANT("Ready to compost and plant"),
		GROWING("Planted");

		@lombok.Getter
		private final String text;

		Task(String text)
		{
			this.text = text;
		}
	}

	static Task task(int value)
	{
		switch (decode(value))
		{
			case READY:
				return Task.PICK;
			case DEAD:
				return Task.CLEAR;
			case DISEASED:
				return Task.CURE;
			case GROWING:
				return Task.GROWING;
			case EMPTY:
				// 0-2 are weeds part-grown, 3 is raked clean; the other empty values are full weeds.
				return value == 3 ? Task.PLANT : Task.RAKE;
			default:
				return Task.PLANT;
		}
	}

	/** The herb patch's varbit, read while you're at it. */
	static int varbit(Patch p)
	{
		return KEYS.get(p)[1];
	}

	/** Region and varbit Time Tracking files each herb patch under. */
	private static final Map<Patch, int[]> KEYS = new EnumMap<>(Patch.class);

	static
	{
		KEYS.put(Patch.FARMING_GUILD, new int[]{4922, VarbitID.FARMING_TRANSMIT_E});
		KEYS.put(Patch.HOSIDIUS, new int[]{6967, VarbitID.FARMING_TRANSMIT_D});
		KEYS.put(Patch.CIVITAS, new int[]{6192, VarbitID.FARMING_TRANSMIT_D});
		KEYS.put(Patch.ARDOUGNE, new int[]{10548, VarbitID.FARMING_TRANSMIT_D});
		KEYS.put(Patch.CATHERBY, new int[]{11062, VarbitID.FARMING_TRANSMIT_D});
		KEYS.put(Patch.FALADOR, new int[]{12083, VarbitID.FARMING_TRANSMIT_D});
		KEYS.put(Patch.MORYTANIA, new int[]{14391, VarbitID.FARMING_TRANSMIT_D});
		KEYS.put(Patch.TROLL_STRONGHOLD, new int[]{11321, VarbitID.FARMING_TRANSMIT_A});
		KEYS.put(Patch.WEISS, new int[]{11325, VarbitID.FARMING_TRANSMIT_A});
		KEYS.put(Patch.HARMONY, new int[]{15148, VarbitID.FARMING_TRANSMIT_B});
	}

	/** Every herb patch Time Tracking knows about, for the current account. */
	static Map<Patch, PatchStatus> read(ConfigManager config, long now)
	{
		Integer offset = config.getRSProfileConfiguration("timetracking", "farmTickOffset", Integer.class);
		Integer precision = config.getRSProfileConfiguration("timetracking", "farmTickOffsetPrecision", Integer.class);
		Map<Patch, PatchStatus> out = new EnumMap<>(Patch.class);
		KEYS.forEach((patch, key) ->
		{
			String stored = config.getRSProfileConfiguration("timetracking", key[0] + "." + key[1]);
			if (stored == null)
			{
				return;
			}
			String[] parts = stored.split(":");
			try
			{
				if (parts.length == 2)
				{
					out.put(patch, of(Integer.parseInt(parts[0]), Long.parseLong(parts[1]), offset, precision, now));
				}
			}
			catch (NumberFormatException ignored)
			{
				// Not a value we understand: treat the patch as unknown.
			}
		});
		return out;
	}
}

package com.potionprep;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.util.Collections;
import java.util.List;
import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.Point;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/** Draws the walk to the run's next patch on the ground, or on the minimap. */
class PathOverlay extends Overlay
{
	private static final Color LINE = new Color(0, 200, 255, 220);

	private final Client client;
	private final boolean minimap;
	/** Scene tiles {x, y}; set on the client thread. */
	private volatile List<int[]> tiles = Collections.emptyList();

	PathOverlay(Client client, boolean minimap)
	{
		this.client = client;
		this.minimap = minimap;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(minimap ? OverlayLayer.ABOVE_WIDGETS : OverlayLayer.ABOVE_SCENE);
	}

	/** Object to outline (the herb patch, once you're there), or null. */
	private volatile net.runelite.api.GameObject outline;

	void set(List<int[]> tiles)
	{
		this.tiles = tiles;
	}

	void setOutline(net.runelite.api.GameObject object)
	{
		this.outline = object;
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		net.runelite.api.GameObject o = outline;
		if (!minimap && o != null)
		{
			java.awt.Shape hull = o.getConvexHull();
			if (hull != null)
			{
				g.setStroke(new BasicStroke(2));
				g.setColor(new Color(0, 200, 255, 40));
				g.fill(hull);
				g.setColor(LINE);
				g.draw(hull);
			}
		}
		List<int[]> path = tiles;
		if (path.size() < 2)
		{
			return null;
		}
		WorldView wv = client.getTopLevelWorldView();
		g.setColor(LINE);
		g.setStroke(new BasicStroke(minimap ? 2 : 3, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		// Start under the player as they move, not at the tile they're stepping to,
		// and draw only the corners so straight runs are one clean line.
		net.runelite.api.Player me = client.getLocalPlayer();
		LocalPoint here = me != null ? me.getLocalLocation() : null;
		java.awt.geom.Path2D.Float line = new java.awt.geom.Path2D.Float();
		boolean open = false;
		for (int i = 0; i < path.size(); i++)
		{
			int[] t = path.get(i);
			boolean corner = i == 0 || i == path.size() - 1
				|| t[0] - path.get(i - 1)[0] != path.get(i + 1)[0] - t[0]
				|| t[1] - path.get(i - 1)[1] != path.get(i + 1)[1] - t[1];
			if (!corner)
			{
				continue;
			}
			LocalPoint lp = i == 0 && here != null ? here : LocalPoint.fromScene(t[0], t[1], wv);
			Point p = minimap ? Perspective.localToMinimap(client, lp) : Perspective.localToCanvas(client, lp, wv.getPlane());
			if (p == null)
			{
				open = false;
				continue;
			}
			if (open)
			{
				line.lineTo(p.getX(), p.getY());
			}
			else
			{
				line.moveTo(p.getX(), p.getY());
				open = true;
			}
		}
		g.draw(line);
		return null;
	}
}

package com.potionprep;

import lombok.Getter;

/** The potions offered in the panel, each the root of a recipe tree. */
@Getter
public enum Potion
{
	ATTACK(Catalog.ATTACK),
	ANTIPOISON(Catalog.ANTIPOISON),
	STRENGTH(Catalog.STRENGTH),
	RESTORE(Catalog.RESTORE),
	ENERGY(Catalog.ENERGY),
	DEFENCE(Catalog.DEFENCE),
	AGILITY(Catalog.AGILITY),
	COMBAT(Catalog.COMBAT),
	PRAYER(Catalog.PRAYER),
	SUPER_ATTACK(Catalog.SUPER_ATTACK),
	SUPERANTIPOISON(Catalog.SUPERANTIPOISON),
	FISHING(Catalog.FISHING),
	SUPER_ENERGY(Catalog.SUPER_ENERGY),
	HUNTER(Catalog.HUNTER),
	SUPER_STRENGTH(Catalog.SUPER_STRENGTH),
	WEAPON_POISON(Catalog.WEAPON_POISON),
	SUPER_RESTORE(Catalog.SUPER_RESTORE),
	SUPER_DEFENCE(Catalog.SUPER_DEFENCE),
	ANTIFIRE(Catalog.ANTIFIRE),
	RANGING(Catalog.RANGING),
	MAGIC(Catalog.MAGIC),
	STAMINA(Catalog.STAMINA),
	ZAMORAK_BREW(Catalog.ZAMORAK_BREW),
	ANTIDOTE_PLUS_PLUS(Catalog.ANTIDOTE_PP),
	SARADOMIN_BREW(Catalog.SARADOMIN_BREW),
	EXTENDED_ANTIFIRE(Catalog.EXTENDED_ANTIFIRE),
	ANTI_VENOM(Catalog.ANTI_VENOM),
	SUPER_COMBAT(Catalog.SUPER_COMBAT),
	SUPER_ANTIFIRE(Catalog.SUPER_ANTIFIRE),
	ANTI_VENOM_PLUS(Catalog.ANTI_VENOM_PLUS),
	EXTENDED_SUPER_ANTIFIRE(Catalog.EXTENDED_SUPER_ANTIFIRE);

	private final Node product;

	Potion(Node product)
	{
		this.product = product;
	}

	public String getName()
	{
		return product.getName();
	}

	public int getLevel()
	{
		return product.getRecipe().getLevel();
	}

	/**
	 * Final crafts per displayed potion. Dose-by-dose recipes (stamina,
	 * extended antifire, anti-venom) are shown as 4-dose potions.
	 */
	public int craftsPerPotion()
	{
		return product.isDosed() && product.getRecipe().getYield() == 1 ? 4 : 1;
	}

	/** Potions you can make from this many final crafts. */
	public int toPotions(int crafts)
	{
		return crafts / craftsPerPotion();
	}

	/** What one displayed potion is, e.g. "Stamina potion(4)", "Prayer potion(3)". */
	public String potionName()
	{
		if (!product.isDosed())
		{
			return getName();
		}
		return getName() + (product.getRecipe().getYield() == 3 ? "(3)" : "(4)");
	}

	@Override
	public String toString()
	{
		return getName() + " (" + getLevel() + ")";
	}
}

package com.potionprep;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.GridLayout;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.EnumMap;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.function.Consumer;
import javax.swing.BorderFactory;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingConstants;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.util.QuantityFormatter;

/**
 * Clickable grid of potion icons. Each tile shows how many you can make
 * with what you have, or the Herblore level you still need.
 */
class PotionGrid extends JPanel
{
	private static final int COLUMNS = 5;
	private static final Color GOOD = new Color(0x5FBF5F);
	private static final Color BAD = new Color(0xE05A5A);
	private static final Color PIE = new Color(0xFFB000);

	private final Map<Potion, Tile> tiles = new EnumMap<>(Potion.class);
	private final Consumer<Potion> onSelect;
	private Potion selected;
	private String filter = "";

	PotionGrid(ItemManager itemManager, Consumer<Potion> onSelect)
	{
		super(new GridLayout(0, COLUMNS, 3, 3));
		this.onSelect = onSelect;
		setOpaque(false);
		for (Potion p : Potion.values())
		{
			Tile t = new Tile(p);
			itemManager.getImage(p.getProduct().getId()).addTo(t.icon);
			tiles.put(p, t);
		}
		layoutTiles();
	}

	void setFilter(String text)
	{
		String f = text == null ? "" : text.trim().toLowerCase(Locale.ROOT);
		if (!f.equals(filter))
		{
			filter = f;
			layoutTiles();
		}
	}

	/** First tile matching the filter, for Enter in the search box. */
	Potion firstVisible()
	{
		for (Potion p : Potion.values())
		{
			if (matches(p))
			{
				return p;
			}
		}
		return null;
	}

	void setSelected(Potion potion)
	{
		selected = potion;
		tiles.values().forEach(Tile::paintState);
	}

	/**
	 * @param boostedLevel current Herblore level, 0 if unknown
	 * @param pie          potions you can only make with a botanical pie
	 */
	void setStats(Map<Potion, Integer> makeable, Map<Potion, Double> xp, int boostedLevel, Set<Potion> pie)
	{
		for (Tile t : tiles.values())
		{
			int lvl = t.potion.getLevel();
			t.pie = pie.contains(t.potion);
			if (!t.pie && boostedLevel > 0 && boostedLevel < lvl)
			{
				t.count.setText("Lv " + lvl);
				t.count.setForeground(BAD);
				t.makeable = -1;
			}
			else
			{
				int n = t.potion.toPotions(makeable.getOrDefault(t.potion, 0));
				t.count.setText(QuantityFormatter.quantityToStackSize(n));
				t.count.setForeground(t.pie ? PIE : n > 0 ? GOOD : ColorScheme.MEDIUM_GRAY_COLOR);
				t.makeable = n;
				t.xp = xp.getOrDefault(t.potion, 0.0);
			}
			t.updateTooltip();
		}
	}

	private boolean matches(Potion p)
	{
		return filter.isEmpty() || p.getName().toLowerCase(Locale.ROOT).contains(filter);
	}

	private void layoutTiles()
	{
		removeAll();
		for (Potion p : Potion.values())
		{
			if (matches(p))
			{
				add(tiles.get(p));
			}
		}
		revalidate();
		repaint();
	}

	private class Tile extends JPanel
	{
		final Potion potion;
		final JLabel icon = new JLabel();
		final JLabel count = new JLabel(" ");
		int makeable;
		double xp;
		boolean pie;
		boolean hover;

		Tile(Potion potion)
		{
			super(new BorderLayout());
			this.potion = potion;
			icon.setHorizontalAlignment(SwingConstants.CENTER);
			count.setHorizontalAlignment(SwingConstants.CENTER);
			count.setFont(FontManager.getRunescapeSmallFont());
			count.setForeground(ColorScheme.MEDIUM_GRAY_COLOR);
			add(icon, BorderLayout.CENTER);
			add(count, BorderLayout.SOUTH);
			updateTooltip();
			paintState();

			addMouseListener(new MouseAdapter()
			{
				@Override
				public void mouseClicked(MouseEvent e)
				{
					onSelect.accept(potion);
				}

				@Override
				public void mouseEntered(MouseEvent e)
				{
					hover = true;
					paintState();
				}

				@Override
				public void mouseExited(MouseEvent e)
				{
					hover = false;
					paintState();
				}
			});
		}

		void updateTooltip()
		{
			String line = makeable < 0 ? "Needs " + potion.getLevel() + " Herblore<br>or "
				+ (potion.getLevel() - PotionPlan.PIE_BOOST) + " with a botanical pie"
				: "Level " + potion.getLevel() + " &middot; can make " + makeable + " &times; " + potion.potionName()
				+ (xp > 0 ? "<br>" + String.format(Locale.US, "%,d", (long) xp) + " xp" : "")
				+ (pie ? "<br>with a botanical pie (+" + PotionPlan.PIE_BOOST + ")" : "");
			setToolTipText("<html>" + potion.getName() + "<br>" + line + "</html>");
		}

		void paintState()
		{
			boolean sel = potion == selected;
			setBackground(sel ? ColorScheme.DARK_GRAY_HOVER_COLOR
				: hover ? ColorScheme.MEDIUM_GRAY_COLOR
				: ColorScheme.DARKER_GRAY_COLOR);
			setBorder(BorderFactory.createLineBorder(sel ? ColorScheme.BRAND_ORANGE : getBackground(), 1));
		}
	}
}

package com.potionprep;

import java.util.ArrayList;
import java.util.Collections;
import java.util.IdentityHashMap;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import lombok.Getter;
import lombok.Value;
import net.runelite.api.gameval.ItemID;

/**
 * Walks a potion's recipe tree against what the player holds: how many can
 * be made, which prep steps (clean, unf, crush, intermediate potions) get
 * there, and what is short. No client access, so it is unit-testable.
 */
@Getter
public final class PotionPlan
{
	@Value
	public static class Row
	{
		String name;
		int itemId;
		int have;
		boolean doses;
	}

	public enum Severity
	{
		ACTION,
		WARNING
	}

	@Value
	public static class Step
	{
		Severity severity;
		String text;
		/** Extra detail for the tooltip, or null. */
		String hint;
	}

	private static final int MAX_UNITS = 1_000_000;

	/** A botanical pie (whole or half) boosts Herblore by 4. */
	public static final int PIE_BOOST = 4;
	public static final int[] PIE_IDS = {ItemID.BOTANICAL_PIE, ItemID.HALF_BOTANICAL_PIE};

	/**
	 * True when your current level is too low for this potion but a
	 * botanical pie on top of your real level would be enough.
	 */
	public static boolean needsPie(Potion potion, int realLevel, int boostedLevel)
	{
		return realLevel > 0 && boostedLevel < potion.getLevel() && realLevel + PIE_BOOST >= potion.getLevel();
	}

	/** The level to plan with: boosted, or real + pie when a pie would unlock it. */
	public static int effectiveLevel(Potion potion, int realLevel, int boostedLevel)
	{
		return needsPie(potion, realLevel, boostedLevel) ? realLevel + PIE_BOOST : boostedLevel;
	}

	private final Potion potion;
	private final List<Row> rows;
	private final List<Step> steps;
	/** Final crafts possible once all prep is done. */
	private final int makeable;
	/** Final crafts possible with no prep at all. */
	private final int makeableNow;

	private PotionPlan(Potion potion, List<Row> rows, List<Step> steps, int makeable, int makeableNow)
	{
		this.potion = potion;
		this.rows = Collections.unmodifiableList(rows);
		this.steps = Collections.unmodifiableList(steps);
		this.makeable = makeable;
		this.makeableNow = makeableNow;
	}

	/**
	 * Every ingredient in the tree, in the order you work through it: each
	 * input's own chain first (grimy, clean, vial, unf, raw, secondary...),
	 * tools last. The finished potion itself is not included.
	 */
	static List<Node> ingredients(Potion potion)
	{
		Set<Node> seen = Collections.newSetFromMap(new IdentityHashMap<>());
		List<Node> out = new ArrayList<>();
		List<Node> tools = new ArrayList<>();
		for (Recipe.Input in : potion.getProduct().getRecipe().getInputs())
		{
			visit(in.getNode(), seen, out, tools);
		}
		for (Node t : tools)
		{
			if (seen.add(t))
			{
				out.add(t);
			}
		}
		return out;
	}

	private static void visit(Node node, Set<Node> seen, List<Node> out, List<Node> tools)
	{
		if (seen.contains(node))
		{
			return;
		}
		Recipe r = node.getRecipe();
		if (r != null)
		{
			for (Recipe.Input in : r.getInputs())
			{
				visit(in.getNode(), seen, out, tools);
			}
			if (r.getTool() != null && !tools.contains(r.getTool()))
			{
				tools.add(r.getTool());
			}
		}
		if (seen.add(node))
		{
			out.add(node);
		}
	}

	static final int BANK_COLUMNS = 8;

	/**
	 * The bank layout: one row per task, in the order you do them. Each row
	 * holds everything that task needs (inputs, then any tool) but not what
	 * it makes; an output only reappears as an input on a later row. Potions
	 * fill their slots with doses (1)-(4). Rows wider than the bank wrap.
	 *
	 * Superantipoison: [grimy irit] / [irit, vial] / [unicorn horn, pestle]
	 * / [irit (unf), unicorn horn dust].
	 */
	public static List<int[]> layoutRows(Potion potion)
	{
		Set<Node> seen = Collections.newSetFromMap(new IdentityHashMap<>());
		List<int[]> rows = new ArrayList<>();
		Recipe fin = potion.getProduct().getRecipe();
		for (Recipe.Input in : fin.getInputs())
		{
			addTasks(in.getNode(), seen, rows);
		}
		addRow(rows, taskIds(fin));
		return rows;
	}

	private static void addTasks(Node node, Set<Node> seen, List<int[]> rows)
	{
		Recipe r = node.getRecipe();
		if (r == null || !seen.add(node))
		{
			return;
		}
		for (Recipe.Input in : r.getInputs())
		{
			addTasks(in.getNode(), seen, rows);
		}
		addRow(rows, taskIds(r));
	}

	private static List<Integer> taskIds(Recipe r)
	{
		List<Integer> ids = new ArrayList<>();
		for (Recipe.Input in : r.getInputs())
		{
			for (int id : in.getNode().rowIds())
			{
				ids.add(id);
			}
		}
		if (r.getTool() != null)
		{
			ids.add(r.getTool().getId());
		}
		return ids;
	}

	private static void addRow(List<int[]> rows, List<Integer> ids)
	{
		for (int i = 0; i < ids.size(); i += BANK_COLUMNS)
		{
			List<Integer> chunk = ids.subList(i, Math.min(ids.size(), i + BANK_COLUMNS));
			rows.add(chunk.stream().mapToInt(Integer::intValue).toArray());
		}
	}

	/** Every distinct item id in the layout. */
	public static List<Integer> layoutItems(Potion potion)
	{
		Set<Integer> ids = new LinkedHashSet<>();
		for (int[] row : layoutRows(potion))
		{
			for (int id : row)
			{
				ids.add(id);
			}
		}
		return new ArrayList<>(ids);
	}

	/**
	 * @param counts        item id to quantity, bank plus inventory
	 * @param herbloreLevel real Herblore level, or 0 if unknown
	 */
	public static PotionPlan compute(Potion potion, Map<Integer, Integer> counts, int herbloreLevel)
	{
		return compute(potion, counts, herbloreLevel, false);
	}

	/**
	 * @param pie the plan assumes a botanical pie; adds it as the first step
	 *            and as an ingredient row
	 */
	public static PotionPlan compute(Potion potion, Map<Integer, Integer> counts, int herbloreLevel, boolean pie)
	{
		Node product = potion.getProduct();
		Recipe fin = product.getRecipe();
		List<Node> nodes = ingredients(potion);

		Map<Node, Integer> base = new IdentityHashMap<>();
		List<Row> rows = new ArrayList<>();
		for (Node n : nodes)
		{
			// Cap so the simulation's arithmetic can never overflow.
			int have = Math.min(n.count(counts), MAX_UNITS);
			base.put(n, have);
			rows.add(new Row(n.getName(), n.getId(), have, n.isDosed()));
		}

		if (pie)
		{
			int pies = counts.getOrDefault(ItemID.BOTANICAL_PIE, 0) + counts.getOrDefault(ItemID.HALF_BOTANICAL_PIE, 0);
			rows.add(0, new Row("Botanical pie", ItemID.BOTANICAL_PIE, pies, false));
		}

		List<Step> steps = new ArrayList<>();
		if (pie)
		{
			int pies = rows.get(0).getHave();
			steps.add(pies > 0
				? new Step(Severity.ACTION, "Eat a botanical pie (+" + PIE_BOOST + ")", "Needs " + potion.getLevel() + " Herblore")
				: new Step(Severity.WARNING, "Need a botanical pie (+" + PIE_BOOST + ")", "Needs " + potion.getLevel() + " Herblore"));
		}
		if (herbloreLevel > 0 && herbloreLevel < fin.getLevel())
		{
			steps.add(new Step(Severity.WARNING, "Needs " + fin.getLevel() + " Herblore", "You have " + herbloreLevel));
			return new PotionPlan(potion, rows, steps, 0, 0);
		}

		// No input yields more than 3 per craft, so this comfortably bounds the search.
		long sum = 1;
		for (int v : base.values())
		{
			sum += (long) v * 3;
		}
		int bound = (int) Math.min(sum, MAX_UNITS * 3L);

		int makeable = maxCrafts(fin, base, herbloreLevel, true, bound);
		int makeableNow = maxCrafts(fin, base, herbloreLevel, false, bound);

		// Prep steps that get you to `makeable`, in the order you would do them.
		Ctx run = new Ctx(base, herbloreLevel, true);
		run.makeFinal(fin, makeable);
		for (Map.Entry<Recipe, Integer> e : run.crafts.entrySet())
		{
			steps.add(new Step(Severity.ACTION, String.format(Locale.US, e.getKey().getStepFormat().replace("%d", "%,d"), e.getValue()), null));
		}

		// What stops you making more? Aim for what your best-stocked input
		// would allow, and list what that needs.
		int target = 0;
		for (Recipe.Input in : fin.getInputs())
		{
			target = Math.max(target, maxForInput(in, base, herbloreLevel, bound));
		}
		Map<String, String> warnings = new LinkedHashMap<>();
		if (target > makeable)
		{
			Ctx want = new Ctx(base, herbloreLevel, true);
			want.makeFinal(fin, target);
			for (Map.Entry<Node, Integer> e : want.shortfalls.entrySet())
			{
				Node n = e.getKey();
				Map<Node, Integer> group = want.groups.get(n);
				if (group != null)
				{
					StringBuilder sb = new StringBuilder(n.getName() + ": short ");
					String sep = "";
					for (Map.Entry<Node, Integer> g : group.entrySet())
					{
						sb.append(sep).append(qty(g.getKey(), g.getValue()));
						sep = ", ";
					}
					warnings.put(sb.toString(), null);
				}
				else
				{
					warnings.put("Short " + qty(n, e.getValue()), n.getSource());
				}
			}
			want.blocked.forEach(b -> warnings.putIfAbsent(b, null));
		}
		run.blocked.forEach(b -> warnings.putIfAbsent(b, null));

		warnings.forEach((text, hint) -> steps.add(new Step(Severity.WARNING, text, hint)));
		if (makeable == 0 && warnings.isEmpty())
		{
			steps.add(new Step(Severity.WARNING, "Nothing found. Open your bank.", null));
		}

		return new PotionPlan(potion, rows, steps, makeable, makeableNow);
	}

	/** Just the "can make" number, for the potion grid. */
	public static int makeable(Potion potion, Map<Integer, Integer> counts, int herbloreLevel)
	{
		return yieldOf(potion, counts, herbloreLevel)[0].intValue();
	}

	/**
	 * Herblore XP for making everything you can of this potion, including the
	 * prep along the way (cleaning herbs, intermediate potions).
	 */
	public static double xp(Potion potion, Map<Integer, Integer> counts, int herbloreLevel)
	{
		return yieldOf(potion, counts, herbloreLevel)[1].doubleValue();
	}

	/** {crafts, xp} */
	private static Number[] yieldOf(Potion potion, Map<Integer, Integer> counts, int herbloreLevel)
	{
		Recipe fin = potion.getProduct().getRecipe();
		if (herbloreLevel > 0 && herbloreLevel < fin.getLevel())
		{
			return new Number[]{0, 0.0};
		}
		Map<Node, Integer> base = new IdentityHashMap<>();
		long sum = 1;
		for (Node n : ingredients(potion))
		{
			int have = Math.min(n.count(counts), MAX_UNITS);
			base.put(n, have);
			sum += (long) have * 3;
		}
		int crafts = maxCrafts(fin, base, herbloreLevel, true, (int) Math.min(sum, MAX_UNITS * 3L));
		Ctx run = new Ctx(base, herbloreLevel, true);
		run.makeFinal(fin, crafts);
		double xp = 0;
		for (Map.Entry<Recipe, Integer> e : run.crafts.entrySet())
		{
			xp += e.getKey().getXp() * e.getValue();
		}
		return new Number[]{crafts, xp};
	}

	private static String qty(Node n, int amount)
	{
		String qty = String.format(Locale.US, "%,d", amount);
		return n.isDosed() ? qty + " doses of " + Catalog.lower(n.getName()) : qty + " " + Catalog.lower(n.getName());
	}

	private static int maxCrafts(Recipe fin, Map<Node, Integer> base, int lvl, boolean allowCraft, int bound)
	{
		int lo = 0;
		int hi = bound;
		while (lo < hi)
		{
			int mid = (lo + hi + 1) >>> 1;
			Ctx c = new Ctx(base, lvl, allowCraft);
			c.makeFinal(fin, mid);
			if (c.shortfalls.isEmpty())
			{
				lo = mid;
			}
			else
			{
				hi = mid - 1;
			}
		}
		return lo;
	}

	/** Most final crafts this one input could supply, ignoring the others. */
	private static int maxForInput(Recipe.Input in, Map<Node, Integer> base, int lvl, int bound)
	{
		int lo = 0;
		int hi = bound;
		while (lo < hi)
		{
			int mid = (lo + hi + 1) >>> 1;
			Ctx c = new Ctx(base, lvl, true);
			c.need(in.getNode(), in.getQty() * mid);
			if (c.shortfalls.isEmpty())
			{
				lo = mid;
			}
			else
			{
				hi = mid - 1;
			}
		}
		return lo;
	}

	/** One simulated attempt: a private copy of the pool, consumed greedily. */
	private static final class Ctx
	{
		final Map<Node, Integer> pool;
		final int lvl;
		final boolean allowCraft;
		final Map<Recipe, Integer> crafts = new LinkedHashMap<>();
		Map<Node, Integer> shortfalls = new LinkedHashMap<>();
		/** Leaf shortages behind a short intermediate potion. */
		final Map<Node, Map<Node, Integer>> groups = new LinkedHashMap<>();
		final Set<String> blocked = new LinkedHashSet<>();

		Ctx(Map<Node, Integer> base, int lvl, boolean allowCraft)
		{
			this.pool = new IdentityHashMap<>(base);
			this.lvl = lvl;
			this.allowCraft = allowCraft;
		}

		void makeFinal(Recipe fin, int n)
		{
			if (n <= 0)
			{
				return;
			}
			for (Recipe.Input in : fin.getInputs())
			{
				need(in.getNode(), in.getQty() * n);
			}
			crafts.merge(fin, n, Integer::sum);
		}

		void need(Node node, int amount)
		{
			int have = pool.getOrDefault(node, 0);
			int take = Math.min(have, amount);
			pool.put(node, have - take);
			int rem = amount - take;
			if (rem == 0)
			{
				return;
			}

			Recipe r = node.getRecipe();
			if (r == null || !allowCraft)
			{
				short_(node, rem);
				return;
			}

			if (lvl > 0 && lvl < r.getLevel())
			{
				blocked.add(capital(r) + ": " + r.getLevel() + " Herblore");
				short_(node, rem);
				return;
			}

			if (r.isAltForm())
			{
				// Cleaning / crushing: limited by the raw form you hold.
				Recipe.Input src = r.getInputs().get(0);
				int crafts = ceilDiv(rem, r.getYield());
				int srcHave = pool.getOrDefault(src.getNode(), 0);
				int can = Math.min(crafts, srcHave / src.getQty());
				if (can > 0 && r.getTool() != null && pool.getOrDefault(r.getTool(), 0) <= 0)
				{
					blocked.add("No " + Catalog.lower(r.getTool().getName()));
					can = 0;
				}
				if (can > 0)
				{
					pool.put(src.getNode(), srcHave - can * src.getQty());
					this.crafts.merge(r, can, Integer::sum);
					int produced = can * r.getYield();
					int used = Math.min(produced, rem);
					pool.merge(node, produced - used, Integer::sum);
					rem -= used;
				}
				if (rem > 0)
				{
					short_(node, rem);
				}
				return;
			}

			int crafts = ceilDiv(rem, r.getYield());
			// Shortages inside an intermediate potion's chain are grouped
			// under that potion, so super combat reads "for super defence:
			// short 10 cadantine" instead of a flat list of leaves.
			Map<Node, Integer> outer = shortfalls;
			Map<Node, Integer> inner = node.isDosed() ? new LinkedHashMap<>() : outer;
			shortfalls = inner;
			for (Recipe.Input in : r.getInputs())
			{
				need(in.getNode(), in.getQty() * crafts);
			}
			shortfalls = outer;
			if (inner != outer && !inner.isEmpty())
			{
				short_(node, rem);
				groups.computeIfAbsent(node, k -> new LinkedHashMap<>()).putAll(inner);
			}
			this.crafts.merge(r, crafts, Integer::sum);
			pool.merge(node, crafts * r.getYield() - rem, Integer::sum);
		}

		private void short_(Node node, int qty)
		{
			shortfalls.merge(node, qty, Integer::sum);
		}

		private static String capital(Recipe r)
		{
			// "Clean %d grimy torstol" -> "Cleaning grimy torstol"
			String s = r.getStepFormat().replace("%d ", "");
			int sp = s.indexOf(' ');
			String verb = sp < 0 ? s : s.substring(0, sp);
			String rest = sp < 0 ? "" : s.substring(sp);
			switch (verb)
			{
				case "Clean":
					return "Cleaning" + rest;
				case "Make":
					return "Making" + rest;
				case "Crush":
					return "Crushing" + rest;
				case "Mix":
					return "Mixing" + rest;
				default:
					return s;
			}
		}

		private static int ceilDiv(int a, int b)
		{
			return (a + b - 1) / b;
		}
	}
}

