package com.potionprep;

import java.util.HashMap;
import java.util.Map;
import java.util.function.IntUnaryOperator;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.VarbitID;

/**
 * What the player has stored with a tool leprechaun, from the game's
 * varbits. These follow the account, so they read the same at any patch.
 */
final class ToolLeprechaun
{
	static final int[] VARBITS = {
		VarbitID.FARMING_TOOLS_RAKE, VarbitID.FARMING_TOOLS_EXTRARAKES,
		VarbitID.FARMING_TOOLS_DIBBER, VarbitID.FARMING_TOOLS_EXTRADIBBERS,
		VarbitID.FARMING_TOOLS_SPADE, VarbitID.FARMING_TOOLS_EXTRASPADES,
		VarbitID.FARMING_TOOLS_SECATEURS, VarbitID.FARMING_TOOLS_EXTRASECATEURS, VarbitID.FARMING_TOOLS_FAIRYSECATEURS,
		VarbitID.FARMING_TOOLS_COMPOST, VarbitID.FARMING_TOOLS_EXTRACOMPOST,
		VarbitID.FARMING_TOOLS_SUPERCOMPOST, VarbitID.FARMING_TOOLS_EXTRASUPERCOMPOST,
		VarbitID.FARMING_TOOLS_ULTRACOMPOST,
		VarbitID.FARMING_TOOLS_BOTTOMLESS_BUCKET_QUANTITY,
		VarbitID.FARMING_TOOLS_BOTTOMLESS_BUCKET_TYPE,
	};

	private ToolLeprechaun()
	{
	}

	/** Item id to quantity stored with the leprechaun. */
	static Map<Integer, Integer> read(IntUnaryOperator varbit)
	{
		Map<Integer, Integer> out = new HashMap<>();
		// Extra-slot varbits count in steps: 2 per step for tools, 256 for compost.
		out.put(ItemID.RAKE, varbit.applyAsInt(VarbitID.FARMING_TOOLS_RAKE) + 2 * varbit.applyAsInt(VarbitID.FARMING_TOOLS_EXTRARAKES));
		out.put(ItemID.DIBBER, varbit.applyAsInt(VarbitID.FARMING_TOOLS_DIBBER) + 2 * varbit.applyAsInt(VarbitID.FARMING_TOOLS_EXTRADIBBERS));
		out.put(ItemID.SPADE, varbit.applyAsInt(VarbitID.FARMING_TOOLS_SPADE) + 2 * varbit.applyAsInt(VarbitID.FARMING_TOOLS_EXTRASPADES));
		int secateurs = varbit.applyAsInt(VarbitID.FARMING_TOOLS_SECATEURS) + 2 * varbit.applyAsInt(VarbitID.FARMING_TOOLS_EXTRASECATEURS);
		out.put(ItemID.FAIRY_ENCHANTED_SECATEURS, varbit.applyAsInt(VarbitID.FARMING_TOOLS_FAIRYSECATEURS) == 1 ? secateurs : 0);
		out.put(ItemID.BUCKET_COMPOST, varbit.applyAsInt(VarbitID.FARMING_TOOLS_COMPOST) + 256 * varbit.applyAsInt(VarbitID.FARMING_TOOLS_EXTRACOMPOST));
		out.put(ItemID.BUCKET_SUPERCOMPOST, varbit.applyAsInt(VarbitID.FARMING_TOOLS_SUPERCOMPOST) + 256 * varbit.applyAsInt(VarbitID.FARMING_TOOLS_EXTRASUPERCOMPOST));
		out.put(ItemID.BUCKET_ULTRACOMPOST, varbit.applyAsInt(VarbitID.FARMING_TOOLS_ULTRACOMPOST));
		// The bottomless bucket, if stored: 1 empty, 2-4 holding compost.
		int bucket = storedBucket(varbit);
		if (bucket >= 2)
		{
			out.put(Farm.BOTTOMLESS_BUCKET, 1);
		}
		else if (bucket == 1)
		{
			out.put(ItemID.BOTTOMLESS_COMPOST_BUCKET, 1);
		}
		out.values().removeIf(n -> n <= 0);
		return out;
	}

	/** The stored bottomless bucket: 0 none, 1 empty, 2 compost, 3 super, 4 ultra. */
	static int storedBucket(IntUnaryOperator varbit)
	{
		return varbit.applyAsInt(VarbitID.FARMING_TOOLS_BOTTOMLESS_BUCKET_TYPE);
	}

	/** Uses in the stored bottomless bucket (0 when none is stored). */
	static int storedBucketUses(IntUnaryOperator varbit)
	{
		return varbit.applyAsInt(VarbitID.FARMING_TOOLS_BOTTOMLESS_BUCKET_QUANTITY);
	}

	/** Compost stored here you can take out at any patch: buckets, or a bucket with some in it. */
	static boolean hasCompost(Map<Integer, Integer> stored)
	{
		for (int id : Farm.COMPOST)
		{
			if (stored.getOrDefault(id, 0) > 0)
			{
				return true;
			}
		}
		return stored.getOrDefault(Farm.BOTTOMLESS_BUCKET, 0) > 0;
	}
}

package com.potionprep;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.Comparator;
import java.util.List;
import java.util.PriorityQueue;
import net.runelite.api.CollisionDataFlag;

/**
 * Shortest walk across the loaded scene, from the game's collision flags:
 * fewest steps over 8 directions (every step is one tick, the same moves
 * the game allows), and of those the one with fewest turns. Coordinates
 * are scene tiles.
 */
final class WalkPath
{
	private WalkPath()
	{
	}

	/** Flags that block a step out of a tile in a direction, indexed by dx+1, dy+1. */
	private static final int[][] OUT = {
		{CollisionDataFlag.BLOCK_MOVEMENT_SOUTH_WEST, CollisionDataFlag.BLOCK_MOVEMENT_WEST, CollisionDataFlag.BLOCK_MOVEMENT_NORTH_WEST},
		{CollisionDataFlag.BLOCK_MOVEMENT_SOUTH, 0, CollisionDataFlag.BLOCK_MOVEMENT_NORTH},
		{CollisionDataFlag.BLOCK_MOVEMENT_SOUTH_EAST, CollisionDataFlag.BLOCK_MOVEMENT_EAST, CollisionDataFlag.BLOCK_MOVEMENT_NORTH_EAST},
	};

	private static final int DIRS = 8;
	private static final int[] DX = {1, -1, 0, 0, 1, 1, -1, -1};
	private static final int[] DY = {0, 0, 1, -1, 1, -1, 1, -1};
	/** A step costs far more than a turn, so turns only break ties. */
	private static final int STEP = 1000;

	private static boolean in(int[][] f, int x, int y)
	{
		return x >= 0 && y >= 0 && x < f.length && y < f[x].length;
	}

	/** A single step, as the game checks it: walls on both sides, and both corners for diagonals. */
	static boolean canStep(int[][] f, int x, int y, int dx, int dy)
	{
		int nx = x + dx;
		int ny = y + dy;
		if (!in(f, nx, ny) || (f[nx][ny] & CollisionDataFlag.BLOCK_MOVEMENT_FULL) != 0)
		{
			return false;
		}
		if ((f[x][y] & OUT[dx + 1][dy + 1]) != 0 || (f[nx][ny] & OUT[1 - dx][1 - dy]) != 0)
		{
			return false;
		}
		if (dx != 0 && dy != 0)
		{
			return canStep(f, x, y, dx, 0) && canStep(f, x, y, 0, dy)
				&& canStep(f, x + dx, y, 0, dy) && canStep(f, x, y + dy, dx, 0);
		}
		return true;
	}

	/**
	 * @param reach how close to the target counts as arrived (patches are objects you stand beside)
	 * @return tiles from start to arrival as {x, y}, or empty if there's no loaded route
	 */
	static List<int[]> find(int[][] f, int sx, int sy, int tx, int ty, int reach)
	{
		return find(f, sx, sy, tx - reach + 1, ty - reach + 1, tx + reach - 1, ty + reach - 1);
	}

	/**
	 * Walk to stand beside an object covering the scene tiles minX..maxX, minY..maxY
	 * (e.g. a herb patch's footprint).
	 */
	static List<int[]> find(int[][] f, int sx, int sy, int minX, int minY, int maxX, int maxY)
	{
		if (f == null || !in(f, sx, sy))
		{
			return Collections.emptyList();
		}
		int w = f.length;
		int h = f[0].length;
		// Dijkstra over (tile, last direction): fewest steps first, then fewest
		// turns, so of the many equally short routes the line takes the clean one.
		int states = w * h * DIRS;
		int[] cost = new int[states];
		int[] parent = new int[states];
		Arrays.fill(cost, Integer.MAX_VALUE);
		PriorityQueue<int[]> queue = new PriorityQueue<>(Comparator.comparingInt((int[] a) -> a[1]));
		int startTile = sx * h + sy;
		// The start has no direction yet: seed it under every one, turn-free.
		for (int d = 0; d < DIRS; d++)
		{
			cost[startTile * DIRS + d] = 0;
			parent[startTile * DIRS + d] = -1;
			queue.add(new int[]{startTile * DIRS + d, 0});
		}
		while (!queue.isEmpty())
		{
			int[] head = queue.poll();
			int state = head[0];
			if (head[1] != cost[state])
			{
				continue;
			}
			int tile = state / DIRS;
			int dir = state % DIRS;
			int x = tile / h;
			int y = tile % h;
			// Beside the area: within one tile of it (or on it, for an open spot).
			int ddx = x < minX ? minX - x : x > maxX ? x - maxX : 0;
			int ddy = y < minY ? minY - y : y > maxY ? y - maxY : 0;
			if (Math.max(ddx, ddy) <= 1)
			{
				List<int[]> path = new ArrayList<>();
				for (int n = state; n != -1; n = parent[n])
				{
					int t = n / DIRS;
					path.add(new int[]{t / h, t % h});
				}
				Collections.reverse(path);
				return path;
			}
			for (int d = 0; d < DIRS; d++)
			{
				int dx = DX[d];
				int dy = DY[d];
				if (!canStep(f, x, y, dx, dy))
				{
					continue;
				}
				int next = ((x + dx) * h + (y + dy)) * DIRS + d;
				int c = head[1] + STEP + (tile == startTile || d == dir ? 0 : 1);
				if (c < cost[next])
				{
					cost[next] = c;
					parent[next] = state;
					queue.add(new int[]{next, c});
				}
			}
		}
		return Collections.emptyList();
	}
}

package com.potionprep;

import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.util.Collections;
import java.util.Map;
import javax.inject.Inject;
import net.runelite.api.widgets.WidgetItem;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.WidgetItemOverlay;
import net.runelite.client.ui.overlay.components.TextComponent;

/**
 * Like Quest Helper's bank tab: in the herb run's bank view, each item shows
 * how many the run needs, green when you have enough, red when short.
 */
class WithdrawOverlay extends WidgetItemOverlay
{
	private static final Color ENOUGH = new Color(0x5FBF5F);
	private static final Color SHORT = new Color(0xE05A5A);

	/** Item id to amount needed; set on the client thread, read while drawing. */
	private volatile Map<Integer, Integer> need = Collections.emptyMap();
	/** Item id to amount you have (bank, inventory, rune pouch). */
	private volatile Map<Integer, Integer> have = Collections.emptyMap();
	private volatile boolean active;

	@Inject
	WithdrawOverlay()
	{
		showOnBank();
	}

	void set(boolean active, Map<Integer, Integer> need, Map<Integer, Integer> have)
	{
		this.need = need;
		this.have = have;
		this.active = active;
	}

	@Override
	public void renderItemOverlay(Graphics2D g, int itemId, WidgetItem item)
	{
		if (!active)
		{
			return;
		}
		Integer n = need.get(itemId);
		if (n == null || n <= 0)
		{
			return;
		}
		Rectangle b = item.getCanvasBounds();
		String text = String.valueOf(n);
		g.setFont(FontManager.getRunescapeSmallFont());
		int w = g.getFontMetrics().stringWidth(text);
		TextComponent t = new TextComponent();
		t.setText(text);
		t.setColor(have.getOrDefault(itemId, 0) >= n ? ENOUGH : SHORT);
		// Bottom right, clear of the stack size in the top left.
		t.setPosition(new java.awt.Point(b.x + b.width - w - 1, b.y + b.height - 1));
		t.render(g);
	}
}

package com.potionprep;

/**
 * Expected herbs from one planted herb patch, using the OSRS Wiki's
 * chance-to-save formula: each harvest has a chance not to use a "life",
 * compost sets the starting lives (3 + 0..3) and how likely disease is.
 */
final class Yield
{
	/** Chance-to-save at 99 Farming, for every herb. */
	static final int HIGH_SAVE = 80;
	/** Disease chance per growth cycle, out of 128, by compost tier (none, compost, super, ultra). */
	private static final int[] DISEASE = {27, 14, 6, 3};

	private Yield()
	{
	}

	/**
	 * @param lowSave chance-to-save at level 1 (out of 256)
	 * @param bonus   added fraction: magic secateurs 0.10, Farming cape 0.05, diaries
	 */
	static double chanceToSave(int lowSave, int level, double bonus)
	{
		double base = Math.floor(lowSave * (99.0 - level) / 98.0 + HIGH_SAVE * (level - 1.0) / 98.0);
		return Math.floor(base * (1 + bonus) + 1) / 256.0;
	}

	/**
	 * @param compost 0 none, 1 compost, 2 supercompost, 3 ultracompost
	 */
	static double expected(int lowSave, int level, double bonus, int compost, boolean diseaseFree)
	{
		int tier = Math.max(0, Math.min(3, compost));
		double herbs = (3 + tier) / (1 - chanceToSave(lowSave, level, bonus));
		// Disease can strike in each of the 3 growth cycles before the crop is grown.
		double survive = diseaseFree ? 1 : Math.pow(1 - DISEASE[tier] / 128.0, 3);
		return herbs * survive;
	}

	/** Snape grass chance-to-save at level 1 and 99, out of 256 (OSRS Wiki yield calculator). */
	static final int SNAPE_LOW = 148;
	static final int SNAPE_HIGH = 195;

	/**
	 * Expected snape grass from one allotment. Compost adds lives; magic secateurs
	 * multiply the chance-to-save constants by 1.1. Disease rates for allotments
	 * aren't known, so this assumes the crop survives.
	 */
	static double snapeGrass(int level, boolean secateurs, int compost)
	{
		double m = secateurs ? 1.10 : 1.0;
		double save = (1 + Math.floor(SNAPE_LOW * m * (99.0 - level) / 98.0 + SNAPE_HIGH * m * (level - 1.0) / 98.0 + 0.5)) / 256.0;
		save = Math.min(save, 0.99);
		int tier = Math.max(0, Math.min(3, compost));
		return (3 + tier) / (1 - save);
	}

	/**
	 * Expected limpwurt roots from one flower patch: 3, plus a random 0..n bonus
	 * where n grows by one every 10 Farming levels from 11 (up to 9 at 91+).
	 * Magic secateurs improve the bonus by about 10%. Compost does nothing.
	 */
	static double limpwurt(int level, boolean secateurs)
	{
		int maxBonus = Math.max(0, Math.min(9, (level - 1) / 10));
		double bonus = maxBonus / 2.0 * (secateurs ? 1.10 : 1.0);
		return 3 + Math.min(bonus, maxBonus);
	}
}

package com.potionprep;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class BottomlessBucketTest
{
	@Test
	public void readsCheckFillAndUse()
	{
		BottomlessBucket b = new BottomlessBucket(-1, 0);
		assertTrue(b.onMessage("Your bottomless compost bucket is currently holding 1,204 uses of ultracompost.", null));
		assertEquals(1204, b.getUses());
		assertEquals(3, b.getType());
		b.onMessage("You fill your bottomless compost bucket with 10 buckets of supercompost.", null);
		b.onMessage("Your bottomless compost bucket now contains a total of 20 uses.", null);
		assertEquals(20, b.getUses());
		assertEquals(2, b.getType());
		// A use is counted at the end of the tick, and only if the bucket was used.
		b.onMessage("You treat the herb patch with supercompost.", false);
		assertFalse(b.onTick());
		b.onMessage("You treat the herb patch with supercompost.", true);
		assertTrue(b.onTick());
		assertEquals(19, b.getUses());
		// If the game says what's left that tick, that wins.
		b.onMessage("You treat the herb patch with supercompost.", true);
		b.onMessage("Your bottomless compost bucket has 18 uses of supercompost remaining.", null);
		assertFalse(b.onTick());
		assertEquals(18, b.getUses());
	}

	@Test
	public void readsTheCheckBoxAndLeprechaun()
	{
		BottomlessBucket b = new BottomlessBucket(-1, 0);
		assertTrue(b.onDialog("Your bottomless compost bucket is currently<br>holding 52 uses of compost."));
		assertEquals(52, b.getUses());
		assertEquals(1, b.getType());
		// Stored with ultracompost (type 4) and 40 uses.
		assertTrue(b.onLeprechaun(4, 40));
		assertEquals(40, b.getUses());
		assertEquals(3, b.getType());
		// Taken out: the varbits go to 0, which says nothing.
		assertFalse(b.onLeprechaun(0, 0));
		assertEquals(40, b.getUses());
		assertTrue(b.onInventory(true, false));
		assertEquals(0, b.getUses());
	}
}

