		FarmPlan plan = FarmPlan.compute(settings(EnumSet.of(Patch.FALADOR), FlowerSeed.NONE, AllotmentSeed.NONE,
			Collections.emptyMap()), new HashMap<>(), new HashSet<>(), a.build());
