		// Pouch first, then the lava runes; no loose law or fire runes needed.
		int[] runeRow = plan.getLayoutRows().stream().filter(r -> r.length > 0 && r[0] == ItemID.DIVINE_RUNE_POUCH)
			.findFirst().orElse(null);
