package com.potionprep;

import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;

public class GearTest
{
	@Test
	public void onlyBankedUnwornGearInEquipmentShape()
	{
		Map<Integer, Integer> bank = new HashMap<>();
		bank.put(ItemID.MM_ALCHEMIST_HAT, 1);
		bank.put(ItemID.AMULET_OF_CHEMISTRY, 5);
		bank.put(ItemID.MM_ALCHEMIST_GLOVES, 1);
		bank.put(ItemID.SKILLCAPE_HERBLORE, 1);
		// Wearing a trimmed cape: the banked untrimmed one still wins;
		// the labcoat is only a placeholder, so it shows faded.
		List<int[]> rows = Gear.rows(id -> bank.getOrDefault(id, 0) > 0,
			id -> id == ItemID.SKILLCAPE_HERBLORE_TRIMMED || id == ItemID.MM_ALCHEMIST_BODY_ALT);
		assertEquals(4, rows.size());
		assertArrayEquals(new int[]{-1, ItemID.MM_ALCHEMIST_HAT, -1}, rows.get(0));
		assertArrayEquals(new int[]{ItemID.SKILLCAPE_HERBLORE, ItemID.AMULET_OF_CHEMISTRY, -1}, rows.get(1));
		assertArrayEquals(new int[]{-1, ItemID.MM_ALCHEMIST_BODY_ALT, -1}, rows.get(2));
		assertArrayEquals(new int[]{ItemID.MM_ALCHEMIST_GLOVES, -1, -1}, rows.get(3));
	}

	@Test
	public void nothingOwned()
	{
		assertEquals(0, Gear.rows(id -> false, id -> false).size());
	}

	@Test
	public void movesBelowWideRows()
	{
		List<boolean[]> occupied = new ArrayList<>();
		occupied.add(new boolean[]{false, false, false, true, true, true, true, true});
		occupied.add(new boolean[]{true, true, true, true, true, true, true, true});
		List<int[]> gear = new ArrayList<>();
		gear.add(new int[]{-1, 1, -1});
		gear.add(new int[]{-1, 2, -1});
		assertEquals(2, Gear.startRow(occupied, gear));
		occupied.remove(1);
		assertEquals(0, Gear.startRow(occupied, gear));
	}

	@Test
	public void savedGearUsesEquipmentTabShape()
	{
		int[] slots = new int[14];
		java.util.Arrays.fill(slots, -1);
		slots[0] = ItemID.GRACEFUL_HOOD;
		slots[1] = ItemID.GRACEFUL_CAPE;
		slots[4] = ItemID.GRACEFUL_TOP;
		slots[7] = ItemID.GRACEFUL_LEGS;
		slots[9] = ItemID.GRACEFUL_GLOVES;
		slots[10] = ItemID.GRACEFUL_BOOTS;
		List<int[]> rows = Gear.fromSlots(slots);
		assertEquals(5, rows.size());
		assertArrayEquals(new int[]{-1, ItemID.GRACEFUL_HOOD, -1}, rows.get(0));
		assertArrayEquals(new int[]{ItemID.GRACEFUL_CAPE, -1, -1}, rows.get(1));
		assertArrayEquals(new int[]{-1, ItemID.GRACEFUL_TOP, -1}, rows.get(2));
		assertArrayEquals(new int[]{-1, ItemID.GRACEFUL_LEGS, -1}, rows.get(3));
		assertArrayEquals(new int[]{ItemID.GRACEFUL_GLOVES, ItemID.GRACEFUL_BOOTS, -1}, rows.get(4));
	}
}

package com.potionprep;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import com.potionprep.Farm.AllotmentSeed;
import com.potionprep.Farm.FlowerSeed;
import com.potionprep.Farm.HerbSeed;
import com.potionprep.Farm.Patch;
import java.util.Collections;
import java.util.EnumSet;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;

public class HerbRunTest
{
	private static HerbRun run(boolean compost, FlowerSeed flower)
	{
		FarmPlan.Settings s = FarmPlan.Settings.builder().herb(HerbSeed.RANARR).flower(flower)
			.allotment(AllotmentSeed.NONE).patches(EnumSet.of(Patch.FALADOR, Patch.WEISS))
			.overrides(Collections.emptyMap()).build();
		Map<Integer, Integer> bank = new HashMap<>();
		bank.put(ItemID.LIMPWURT_SEED, 10);
		if (compost)
		{
			bank.put(ItemID.BUCKET_ULTRACOMPOST, 10);
		}
		FarmPlan plan = FarmPlan.compute(s, bank, new HashSet<>(), 99);
		return HerbRun.from(plan, s, 0);
	}

	@Test
	public void stopIsDoneOncePlantedAndComposted()
	{
		HerbRun r = run(true, FlowerSeed.LIMPWURT);
		assertEquals(Patch.FALADOR, r.current().getPatch());
		assertEquals(2, r.current().getPlots().size());
		r.onMessage("You treat the herb patch with ultracompost.");
		r.onMessage("You plant a Ranarr seed in the herb patch.");
		assertEquals(Patch.FALADOR, r.current().getPatch());
		r.onMessage("You plant a Limpwurt seed in the flower patch.");
		// Flower still needs compost.
		assertEquals(Patch.FALADOR, r.current().getPatch());
		r.onMessage("This flower patch has already been treated with ultracompost.");
		assertEquals(Patch.WEISS, r.current().getPatch());
	}

	@Test
	public void withoutCompostPlantingIsEnough()
	{
		HerbRun r = run(false, FlowerSeed.NONE);
		assertFalse(r.isCompost());
		r.onMessage("You plant a Ranarr seed in the herb patch.");
		assertEquals(Patch.WEISS, r.current().getPatch());
		r.skip();
		assertTrue(r.finished());
	}

	@Test
	public void otherMessagesAreIgnored()
	{
		HerbRun r = run(true, FlowerSeed.NONE);
		assertFalse(r.onMessage("You pick a Grimy ranarr weed."));
	}

	@Test
	public void farmingGuildAllotmentsAreTheirOwnStop()
	{
		FarmPlan.Settings s = FarmPlan.Settings.builder().herb(HerbSeed.RANARR).flower(FlowerSeed.LIMPWURT)
			.allotment(AllotmentSeed.SNAPE_GRASS).patches(EnumSet.of(Patch.FARMING_GUILD))
			.overrides(Collections.emptyMap()).build();
		Map<Integer, Integer> seeds = new HashMap<>();
		seeds.put(ItemID.LIMPWURT_SEED, 10);
		seeds.put(ItemID.SNAPE_GRASS_SEED, 30);
		HerbRun r = HerbRun.from(FarmPlan.compute(s, seeds, new HashSet<>(), 99), s, 0);
		assertEquals(2, r.getStops().size());
		assertEquals(1, r.getStops().get(0).getPlots().size());
		assertEquals("Farming Guild allotments", r.getStops().get(1).getName());
		assertEquals(3, r.getStops().get(1).getPlots().size());
		assertEquals(null, r.getStops().get(1).getTeleport());
	}

	@Test
	public void liveHerbStateDrivesTheSteps()
	{
		HerbRun r = run(false, FlowerSeed.NONE);
		r.onHerbState(PatchStatus.task(37)); // ranarr ready
		HerbRun.Plot herb = r.current().getPlots().get(0);
		assertEquals("pick the herbs, plant ranarr seed", HerbRun.todo(herb, false));
		r.onHerbState(PatchStatus.task(171)); // dead
		assertEquals("clear the dead herbs (spade), plant ranarr seed", HerbRun.todo(herb, false));
		r.onHerbState(PatchStatus.task(3)); // raked clean
		assertEquals("plant ranarr seed", HerbRun.todo(herb, false));
		r.onHerbState(PatchStatus.task(32)); // planted
		assertEquals(Patch.WEISS, r.current().getPatch());
	}

	@Test
	public void runningOutOfCompostKeepsTheRunGoing()
	{
		HerbRun r = run(true, FlowerSeed.NONE);
		r.onMessage("You plant a Ranarr seed in the herb patch.");
		// Planted but not composted: still at Falador.
		assertEquals(Patch.FALADOR, r.current().getPatch());
		assertTrue(r.setCompostCarried(false));
		assertEquals(Patch.WEISS, r.current().getPatch());
		assertEquals("Plant", HerbRun.status(r.current().getPlots().get(0), r.isCompost()));
	}

	@Test
	public void compostGoesOnBeforeOrAfterTheSeed()
	{
		HerbRun r = run(true, FlowerSeed.NONE);
		HerbRun.Plot herb = r.current().getPlots().get(0);
		assertEquals("Plant + compost", HerbRun.status(herb, r.isCompost()));
		// Seed first, then compost.
		r.onMessage("You plant a Ranarr seed in the herb patch.");
		assertEquals("Compost", HerbRun.status(herb, r.isCompost()));
		assertEquals(Patch.FALADOR, r.current().getPatch());
		r.onMessage("You treat the herb patch with ultracompost.");
		assertEquals(Patch.WEISS, r.current().getPatch());
		// Compost first (here by Fertile Soil), then seed.
		herb = r.current().getPlots().get(0);
		r.onMessage("The herb patch has been treated with supercompost.");
		assertEquals("Plant", HerbRun.status(herb, r.isCompost()));
		r.onMessage("You plant a Ranarr seed in the herb patch.");
		assertTrue(r.finished() || r.current().getPatch() != Patch.WEISS);
	}

	@Test
	public void allotmentsOnlyWhileSeedsLast()
	{
		FarmPlan.Settings s = FarmPlan.Settings.builder().herb(HerbSeed.RANARR).flower(FlowerSeed.NONE)
			.allotment(AllotmentSeed.SNAPE_GRASS).patches(EnumSet.of(Patch.FALADOR, Patch.CATHERBY))
			.overrides(Collections.emptyMap()).build();
		Map<Integer, Integer> bank = new HashMap<>();
		bank.put(ItemID.SNAPE_GRASS_SEED, 2);
		HerbRun r = HerbRun.from(FarmPlan.compute(s, bank, new HashSet<>(), 99), s, 0);
		// 2 seeds can't plant an allotment (3 each): herb plots only.
		assertEquals(1, r.getStops().get(0).getPlots().size());
		bank.put(ItemID.SNAPE_GRASS_SEED, 9);
		r = HerbRun.from(FarmPlan.compute(s, bank, new HashSet<>(), 99), s, 0);
		assertEquals(3, r.getStops().get(0).getPlots().size());
		assertEquals(2, r.getStops().get(1).getPlots().size());
	}

	@Test
	public void plotsWithoutSeedsDontHoldUpTheStop()
	{
		HerbRun r = run(false, FlowerSeed.LIMPWURT);
		Map<HerbRun.PlotType, Integer> carried = new java.util.EnumMap<>(HerbRun.PlotType.class);
		carried.put(HerbRun.PlotType.HERB, 5);
		r.setSeedsCarried(carried);
		assertEquals("No seeds", HerbRun.status(r.current().getPlots().get(1), false));
		r.onMessage("You plant a Ranarr seed in the herb patch.");
		assertEquals(Patch.WEISS, r.current().getPatch());
	}

	@Test
	public void leavingAPlantedStopMovesOn()
	{
		HerbRun r = run(true, FlowerSeed.LIMPWURT);
		r.onPosition(true);
		r.onMessage("You plant a Ranarr seed in the herb patch.");
		// Herb planted, flower and compost left: still Falador while you're there.
		r.onPosition(true);
		assertEquals(Patch.FALADOR, r.current().getPatch());
		assertTrue(r.onPosition(false));
		assertEquals(Patch.WEISS, r.current().getPatch());
	}

	@Test
	public void notVisitedYetDoesntMoveOn()
	{
		HerbRun r = run(true, FlowerSeed.NONE);
		assertFalse(r.onPosition(false));
		assertEquals(Patch.FALADOR, r.current().getPatch());
	}
}

package com.potionprep;

import static org.junit.Assert.assertEquals;
import com.potionprep.PatchStatus.State;
import org.junit.Test;

public class PatchStatusTest
{
	@Test
	public void decodesHerbValues()
	{
		assertEquals(State.EMPTY, PatchStatus.decode(0));
		assertEquals(State.EMPTY, PatchStatus.decode(3));
		assertEquals(State.GROWING, PatchStatus.decode(32)); // ranarr seed
		assertEquals(State.GROWING, PatchStatus.decode(35));
		assertEquals(State.READY, PatchStatus.decode(36)); // ranarr, 3 lives
		assertEquals(State.READY, PatchStatus.decode(38));
		assertEquals(State.GROWING, PatchStatus.decode(39)); // toadflax
		assertEquals(State.READY, PatchStatus.decode(66)); // huasca
		assertEquals(State.EMPTY, PatchStatus.decode(67));
		assertEquals(State.READY, PatchStatus.decode(109)); // torstol
		assertEquals(State.DISEASED, PatchStatus.decode(140));
		assertEquals(State.DEAD, PatchStatus.decode(171));
		assertEquals(State.READY, PatchStatus.decode(197)); // goutweed
		assertEquals(State.DEAD, PatchStatus.decode(202));
		assertEquals(State.UNKNOWN, PatchStatus.decode(120));
	}

	@Test
	public void predictsWhenGrowingHerbsAreReady()
	{
		long seen = 1_800_000_000L - 1_800_000_000L % 1200; // on a 20 min tick
		// Just planted (stage 0): 4 more ticks.
		PatchStatus s = PatchStatus.of(32, seen, null, null, seen + 60);
		assertEquals(State.GROWING, s.getState());
		assertEquals(seen + 4 * 1200, s.getReadyAt());
		// Long since: predicted ready.
		assertEquals(State.READY, PatchStatus.of(32, seen, null, null, seen + 5 * 1200).getState());
	}
}

package com.potionprep;

import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import java.util.Arrays;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;

public class PotionPlanTest
{
	private static Map<Integer, Integer> counts(int... pairs)
	{
		Map<Integer, Integer> m = new HashMap<>();
		for (int i = 0; i < pairs.length; i += 2)
		{
			m.put(pairs[i], pairs[i + 1]);
		}
		return m;
	}

	private static String steps(PotionPlan plan)
	{
		return plan.getSteps().stream().map(PotionPlan.Step::getText).collect(Collectors.joining(" | "));
	}

	@Test
	public void xpIncludesPrepSteps()
	{
		Map<Integer, Integer> c = new java.util.HashMap<>();
		c.put(ItemID.UNIDENTIFIED_RANARR, 10);
		c.put(ItemID.VIAL_WATER, 10);
		c.put(ItemID.SNAPE_GRASS, 10);
		// 10 x clean (7.5) + 10 x mix (87.5); the unf step gives none.
		assertEquals(950.0, PotionPlan.xp(Potion.PRAYER, c, 99), 0.001);
	}

	@Test
	public void oneRowPerTaskWithInputsButNotOutput()
	{
		List<int[]> rows = PotionPlan.layoutRows(Potion.SUPERANTIPOISON);
		assertEquals(4, rows.size());
		assertArrayEquals(new int[]{ItemID.UNIDENTIFIED_IRIT}, rows.get(0));
		assertArrayEquals(new int[]{ItemID.IRIT_LEAF, ItemID.VIAL_WATER}, rows.get(1));
		assertArrayEquals(new int[]{ItemID.UNICORN_HORN, ItemID.PESTLE_AND_MORTAR}, rows.get(2));
		assertArrayEquals(new int[]{ItemID.IRITVIAL, ItemID.UNICORN_HORN_DUST}, rows.get(3));
	}

	@Test
	public void plainSecondaryHasNoTaskRowOfItsOwn()
	{
		List<int[]> rows = PotionPlan.layoutRows(Potion.PRAYER);
		assertEquals(3, rows.size());
		assertArrayEquals(new int[]{ItemID.RANARRVIAL, ItemID.SNAPE_GRASS}, rows.get(2));
	}

	@Test
	public void staminaTasksChainThroughSuperEnergy()
	{
		List<int[]> rows = PotionPlan.layoutRows(Potion.STAMINA);
		assertEquals(4, rows.size());
		assertArrayEquals(new int[]{ItemID.AVANTOEVIAL, ItemID.MORTMYREMUSHROOM}, rows.get(2));
		assertArrayEquals(new int[]{ItemID._1DOSE2ENERGY, ItemID._2DOSE2ENERGY, ItemID._3DOSE2ENERGY, ItemID._4DOSE2ENERGY,
			ItemID.AMYLASE}, rows.get(3));
		assertFalse(PotionPlan.layoutItems(Potion.STAMINA).contains(ItemID._4DOSESTAMINA));
	}

	@Test
	public void rowsFitTheBankAndSkipTheFinishedPotion()
	{
		for (Potion p : Potion.values())
		{
			for (int[] row : PotionPlan.layoutRows(p))
			{
				assertTrue(p.name(), row.length >= 1 && row.length <= PotionPlan.BANK_COLUMNS);
			}
			for (int id : p.getProduct().rowIds())
			{
				assertFalse(p.name(), PotionPlan.layoutItems(p).contains(id));
			}
		}
	}

	@Test
	public void readyWhenUnfAndSecondaryInHand()
	{
		PotionPlan plan = PotionPlan.compute(Potion.PRAYER, counts(ItemID.RANARRVIAL, 14, ItemID.SNAPE_GRASS, 20), 99);
		assertEquals(14, plan.getMakeable());
		assertEquals(14, plan.getMakeableNow());
		String s = steps(plan);
		assertTrue(s, s.contains("Mix 14 prayer potions"));
		assertTrue(s, s.contains("Short 6 ranarr weed"));
	}

	@Test
	public void cleansAndMixesGrimyHerbs()
	{
		PotionPlan plan = PotionPlan.compute(Potion.PRAYER, counts(ItemID.UNIDENTIFIED_RANARR, 10, ItemID.RANARR_WEED, 4,
			ItemID.VIAL_WATER, 100, ItemID.SNAPE_GRASS, 100), 99);
